const t=[{id:"l.rc-deep.bored",xp:30,title:{en:"Put a building next door (or make the pile wider than 60 cm): driving is ruled out",ar:"حط مبنى جار (أو خلّي الخازوق أعرض من 60 سم): الدق بيترفض"},check:e=>e.mode==="type"&&!e.drivenOk&&e.boredOk},{id:"l.rc-deep.tremie",xp:40,title:{en:"Play a bored pile under bentonite to its last step: tremie concrete, then the broken head",ar:"شغّل خازوق حفر تحت البنتونيت لآخر خطوة: الصب بماسورة الصب، وبعدين تكسير الرأس"},check:e=>e.mode==="type"&&e.method==="bentonite"&&e.stageDone},{id:"l.rc-deep.cfa",xp:30,title:{en:"Play the C.F.A. sequence to the end: concrete first, cage second",ar:"شغّل خطوات الـ C.F.A. للآخر: الخرسانة الأول والقفص بعدها"},check:e=>e.mode==="type"&&e.method==="cfa"&&e.stageDone}],a=[{id:"l.rc-deep.drag",xp:40,title:{en:"Make the drag cost more than 25 % of Q_all",ar:"خلّي السحب ياكل أكتر من 25 % من Q_all"},hint:{en:"Select the clay layer (L2) and make it stiffer (larger C) or thicker — its drag is α·C over its whole height.",ar:"اختار طبقة الطين (L2) وخلّيها أقوى (C أكبر) أو أسمك — سحبها α·C على ارتفاعها كله."},check:e=>e.mode==="capacity"&&e.nsf&&e.negLoss>.25},{id:"l.rc-deep.embed",xp:30,title:{en:"Raise the tip until it is less than 3d into the sand: that layer's friction disappears",ar:"طلّع الطرف لحد ما يبقى داخل الرمل أقل من 3d: احتكاك الطبقة دي بيختفي"},check:e=>e.mode==="capacity"&&!e.embedOk},{id:"l.rc-deep.concrete",xp:40,title:{en:"Make the concrete, not the soil, govern Q_all (try a driven square pile without the drag)",ar:"خلّي الخرسانة، مش التربة، هي اللي تحكم Q_all (جرّب خازوق دق مربع من غير السحب)"},check:e=>e.mode==="capacity"&&e.structuralGoverns}],i=[{id:"l.rc-deep.working",xp:30,title:{en:"Make it a working-pile test (stop at 150 %): Brinch Hansen can no longer be found",ar:"خلّيه اختبار خازوق عامل (وقّف عند 150 %): برينش هانسن مش هيتلاقي"},check:e=>e.mode==="dynamic"&&e.sub==="test"&&!e.toFailure&&!e.bhFound},{id:"l.rc-deep.hiley",xp:40,title:{en:"Switch to the Hiley formula and find a hammer and a set that give Q_all ≥ 600 kN",ar:"روح لمعادلة هايلي واختار مطرقة وهبوط دائم يدّوا Q_all ≥ 600 kN"},check:e=>e.mode==="dynamic"&&e.sub==="hiley"&&e.hileyQall>=600}],n=[{id:"l.rc-deep.pull",xp:40,title:{en:"Pull a pile: raise M_y until the lightest pile is in tension (Q_min < 0)",ar:"اشد خازوق: زوّد M_y لحد ما أخف خازوق يتشد (Q_min < 0)"},hint:{en:"With the automatic n the group just grows; untick it and take fewer piles, or lower P.",ar:"مع n التلقائي المجموعة بتكبر وخلاص؛ شيل العلامة وخد خوازيق أقل، أو قلّل P."},check:e=>e.mode==="cap"&&e.tension},{id:"l.rc-deep.survive",xp:50,title:{en:"Find a pile the group can lose: mark it defective and keep every other pile ≤ Q_all and none pulled",ar:"دوّر على خازوق المجموعة تقدر تستغنى عنه: خلّيه معيوب وخلّي كل الباقي ≤ Q_all ومفيش خازوق بيتشد"},check:e=>e.mode==="cap"&&e.defective&&!e.overCap&&!e.tension}],s=[{id:"l.rc-deep.strap",xp:50,title:{en:"Fix cap 1: three piles in its first row (or a larger e) until the strap beam is valid",ar:"صلّح الهامة 1: تلات خوازيق في أول صف (أو e أكبر) لحد ما كمرة الرباط تبقى صالحة"},check:e=>e.mode==="property"&&e.pkind==="strap"&&e.strapOk},{id:"l.rc-deep.combined",xp:50,title:{en:"Bring the columns 4.0 m apart or closer, switch to a combined cap and find rows with 3d ≤ X ≤ 6d",ar:"قرّب العمودين لـ 4.0 م أو أقل، وروح للهامة المشتركة ودوّر على صفوف تدّي 3d ≤ X ≤ 6d"},check:e=>e.mode==="property"&&e.pkind==="combined"&&e.combinedOk&&e.propS<=4+1e-9}],o={sections:[{id:"why",title:{en:"When the ground near the surface is too weak: piles",ar:"لما التربة اللي قريبة من السطح تبقى ضعيفة: الخوازيق"},blocks:[{t:"p",text:{en:"A footing spreads a column load over the ground right under it. When the strong layer lies deep — soft clay, loose fill or waterlogged silt near the surface — a footing would have to be enormous, or it would settle too much. A **deep foundation** takes the load down to a stronger layer, or collects it gradually along a long shaft. The usual deep foundation is a group of **piles** (خوازيق) joined at the top by a **pile cap** (هامة الخوازيق).",ar:"القاعدة بتفرش حمل العمود على التربة اللي تحتها على طول. لكن لما الطبقة القوية تبقى عميقة — طين طري أو ردم سايب أو طمي مشبّع بالمية قريب من السطح — القاعدة كانت هتبقى ضخمة جداً، أو هتهبط أكتر من اللازم. **الأساسات العميقة** بتنزّل الحمل لطبقة أقوى، أو بتجمّعه شوية شوية على جذع طويل. والأساس العميق المعتاد هو مجموعة **خوازيق** متربطة من فوق بـ**هامة الخوازيق** (`Pile cap`)."}},{t:"eq",tex:["D_f > B,\\qquad D_f \\ge 4.0,\\qquad L \\ge 10\\,d"],caption:{en:"A foundation is deep when both conditions on its depth D_f hold (B = its width, m). A pile is at least ten times as long as its side or diameter d.",ar:"الأساس بيبقى عميق لما الشرطين على عمقه D_f يتحققوا مع بعض (B = عرضه، م). والخازوق طوله على الأقل عشر أضعاف ضلعه أو قطره d."}},{t:"p",text:{en:`Piles are chosen when:
- heavy loads sit on a thick weak layer with a firm layer (dense sand, stiff clay, rock) deeper down;
- the moment is large compared with the vertical load — tall, light structures such as towers and chimneys — so some piles must work in **tension**;
- something wants to float: a buried tank or a basement below the water table pulls its piles **up**;
- large horizontal forces act (bridges, retaining structures, wind on masts);
- the sides of a deep excavation need support: **sheet piles**, or rows of bored piles touching each other (**tangent**) or cutting into each other (**secant**);
- a slope has to be pinned against sliding.`,ar:"بنختار الخوازيق لما:\n- أحمال تقيلة قاعدة على طبقة ضعيفة سميكة وتحتها طبقة قوية (رمل كثيف، طين متماسك، صخر)؛\n- العزم كبير قصاد الحمل الرأسي — منشآت عالية وخفيفة زي الأبراج والمداخن — فشوية خوازيق لازم تشتغل **شد**؛\n- فيه حاجة عايزة تطفو: خزان مدفون أو بدروم تحت منسوب المياه الجوفية بيشد خوازيقه **لفوق**؛\n- فيه قوى أفقية كبيرة (كباري، منشآت سند، رياح على صواري)؛\n- جوانب حفر عميق محتاجة سند: **ستائر لوحية** (`Sheet piles`)، أو صفوف خوازيق حفر لامسة بعض (`Tangent`) أو قاطعة في بعض (`Secant`)؛\n- ميل تربة محتاج يتثبت ضد الانزلاق."}},{t:"quiz",q:{kind:"mcq",q:{en:"A footing 2.5 m wide is founded 3.0 m below the ground. Is it a deep foundation?",ar:"قاعدة عرضها 2.5 م ومنسوب تأسيسها 3.0 م تحت سطح الأرض. هل ده أساس عميق؟"},options:[{en:"No — D_f > B, but D_f < 4.0 m",ar:"لأ — D_f > B، بس D_f < 4.0 م"},{en:"Yes — D_f > B is enough",ar:"آه — D_f > B كفاية"},{en:"Yes — anything below 2 m is deep",ar:"آه — أي حاجة تحت 2 م عميقة"}],answer:0,explain:{en:"Both conditions are needed: $3.0 > 2.5$ but $3.0 < 4.0$, so it is still a shallow footing.",ar:"لازم الشرطين: $3.0 > 2.5$ بس $3.0 < 4.0$، فهي لسه قاعدة ضحلة."}}}]},{id:"types",title:{en:"The pile family, and how each one is built",ar:"عيلة الخوازيق، وكل نوع بيتنفذ إزاي"},blocks:[{t:"p",text:{en:"**By material:** steel piles (sheet piles, pipes, H-sections), timber piles, and concrete piles — prestressed, reinforced **precast**, or **cast in place**. **By installation:** a pile is either **driven** — forced into the ground so that it pushes the soil aside and compacts it — or **bored** — the soil is taken out and replaced by concrete. Cast-in-place piles are made in three ways: bored, driven, and **C.F.A.** (continuous flight auger).",ar:"**حسب المادة:** خوازيق حديد (ستائر لوحية، مواسير، قطاعات H)، وخوازيق خشب، وخوازيق خرسانة — سابقة الإجهاد، أو مسلحة **سابقة الصب**، أو **بتتصب في مكانها**. **حسب التنفيذ:** الخازوق يا إما **دق** — بيتزق في الأرض فيزيح التربة ويدمكها — يا إما **حفر** — التربة بتطلع وبتتعوض بخرسانة. والخوازيق اللي بتتصب في مكانها ليها تلات طرق: الحفر، والدق، والـ `C.F.A.` (بريمة مستمرة)."}},{t:"table",head:[{en:"Pile",ar:"الخازوق"},{en:"Sizes",ar:"المقاسات"},{en:"Strong points",ar:"مميزاته"},{en:"Watch out",ar:"خلّي بالك"}],rows:[[{en:"Precast, driven",ar:"سابق الصب، دق"},{en:"0.40–0.50 m square or 0.40 m round, up to about 12 m",ar:"مربع 0.40–0.50 م أو دايري 0.40 م، لحد حوالي 12 م"},{en:"good concrete made in the yard; the set per blow measures the capacity",ar:"خرسانة جيدة معمولة في الموقع؛ والهبوط لكل ضربة بيقيس القدرة"},{en:"vibration: not beside existing buildings (open trenches reduce it); splices beyond 12 m",ar:"الاهتزاز: مش جنب مباني قايمة (الخنادق المفتوحة بتقلله)؛ ووصلات بعد 12 م"}],[{en:"Driven, cast in place",ar:"دق، بيتصب في مكانه"},{en:"Ø up to 0.60 m, 12–20 m long",ar:"Ø لحد 0.60 م، طول 12–20 م"},{en:"fast; compacting the soil raises the skin friction",ar:"سريع؛ ودمك التربة بيزوّد الاحتكاك الجانبي"},{en:"vibration; drive from the middle of the site outwards; cannot pass very hard layers",ar:"اهتزاز؛ الدق من نص الموقع لبرّه؛ ومايعدّيش طبقات صلبة جداً"}],[{en:"Bored",ar:"حفر"},{en:"Ø up to 1.50 m, 50–60 m long",ar:"Ø لحد 1.50 م، طول 50–60 م"},{en:"any soil including rock; no vibration",ar:"أي تربة حتى الصخر؛ من غير اهتزاز"},{en:"slow; the hole must be held open",ar:"بطيء؛ والحفرة لازم تتسند"}],[{en:"C.F.A.",ar:"C.F.A."},{en:"auger as long as the pile",ar:"بريمة طولها قد الخازوق"},{en:"the hole is never open; less spoil than the pile volume",ar:"الحفرة عمرها ما بتتفتح؛ والناتج أقل من حجم الخازوق"},{en:"the cage is pushed into fresh concrete",ar:"القفص بيتزق في خرسانة طرية"}]]},{t:"p",text:{en:"**Holding a bored hole open.** The soil is dug out in stages of 1–3 m with a **bucket** (الكباش) or an **auger** (البريمة). In strong soil without ground water the hole stands by itself — **dry boring**. Otherwise: a steel **casing** (القيسون), practical for short piles up to about 12 m; or **bentonite slurry**, a clay suspension of 1.02–1.05 t/m³ kept above the water level: its pressure on the wall is larger than the pressure of the ground water, and it plasters the wall with a thin **mud cake** — which also lowers the skin friction a little. The concrete goes in from the bottom through a **tremie pipe** (ماسورة الصب) whose end always stays buried in the fresh concrete, so the rising concrete pushes the slurry out without mixing with it.",ar:"**إزاي الحفرة تفضل مفتوحة.** التربة بتطلع على مراحل 1–3 م بـ**الكباش** أو **البريمة**. في التربة القوية اللي مفيهاش مياه جوفية الحفرة بتقف لوحدها — **حفر جاف**. غير كده: **القيسون** (ماسورة صلب)، عملي للخوازيق القصيرة لحد حوالي 12 م؛ أو **البنتونيت**، طين معلّق في مية كثافته 1.02–1.05 طن/م³ بيفضل أعلى من منسوب المية: ضغطه على الجدار أكبر من ضغط المياه الجوفية، وبيلبّس الجدار طبقة طين رقيقة (`Mud cake`) — ودي كمان بتقلل الاحتكاك الجانبي شوية. والخرسانة بتتصب من تحت بـ**ماسورة الصب** (`Tremie`) وطرفها دايماً مدفون في الخرسانة الطرية، فالخرسانة وهي طالعة بتطرد البنتونيت من غير ما تختلط بيه."}},{t:"p",text:{en:"**A driven cast-in-place pile** starts as a steel tube closed at its toe by a **plug** (الطبة). The hammer drives it to level, the cage goes down inside the dry tube, and the tube is pulled out while the concrete is placed — the plug stays in the ground. **C.F.A.** screws a hollow auger as long as the pile to full depth; the soil stays on its flights, so the hole is never open. Concrete is pumped down the stem as the auger comes out, and only then is the cage pushed into the fresh concrete: **concrete first, cage second** — the natural order wherever ground water would flood an open hole.",ar:"**خازوق الدق اللي بيتصب في مكانه** بيبدأ بماسورة صلب مقفولة من تحت بـ**الطبة**. المطرقة بتدقها لحد المنسوب، والقفص بينزل جوه الماسورة الناشفة، والماسورة بتتسحب والخرسانة بتتصب — والطبة بتفضل في الأرض. أما **الـ C.F.A.** فبتلف بريمة مفرغة طولها قد الخازوق لحد العمق كله؛ التربة بتفضل على ريشها فالحفرة عمرها ما بتتفتح. الخرسانة بتتضخ من عمود البريمة وهي طالعة، وبعدها بس القفص بيتزق في الخرسانة الطرية: **الخرسانة الأول والقفص بعدها** — وده الترتيب الطبيعي في أي مكان المياه الجوفية ممكن تغرق فيه الحفرة المفتوحة."}},{t:"lab",lab:"piles",height:500,props:{preset:"type",missions:t},caption:{en:"Switch the site conditions: the pile-type table allows or forbids each method. Pick a method and press Play — casing, bentonite and its mud cake, the tremie, a driven tube with its plug, a precast pile, the C.F.A. auger — and the broken head at the end.",ar:"غيّر ظروف الموقع: جدول نوع الخازوق بيسمح أو بيمنع كل طريقة. اختار طريقة واضغط تشغيل — القيسون، والبنتونيت وطبقة الطين، وماسورة الصب، والماسورة المدقوقة بطبتها، والخازوق سابق الصب، وبريمة الـ C.F.A. — وتكسير الرأس في الآخر."}},{t:"quiz",q:{kind:"mcq",q:{en:"Why must the bentonite in a bored hole stand above the ground-water level?",ar:"ليه البنتونيت في حفرة الخازوق لازم يفضل أعلى من منسوب المياه الجوفية؟"},options:[{en:"So that its pressure on the wall is larger than the water pressure outside",ar:"عشان ضغطه على الجدار يبقى أكبر من ضغط المية اللي برّه"},{en:"So that it cures the concrete",ar:"عشان يعالج الخرسانة"},{en:"So that the cage floats into place",ar:"عشان القفص يطفو لمكانه"}],answer:0,explain:{en:"The slurry (1.02–1.05 t/m³) holds the wall only while its pressure exceeds the water pressure; it also leaves a mud cake on the wall.",ar:"البنتونيت (1.02–1.05 طن/م³) بيسند الجدار طول ما ضغطه أكبر من ضغط المية؛ وكمان بيسيب طبقة طين على الجدار."}}}]},{id:"choose",title:{en:"Choosing the type; breaking the heads; how a pile carries its load",ar:"اختيار النوع؛ تكسير الرؤوس؛ الخازوق بيشيل حمله إزاي"},blocks:[{t:"table",head:[{en:"Condition",ar:"الشرط"},{en:"Driven",ar:"دق"},{en:"Bored",ar:"حفر"}],rows:[[{en:"square section",ar:"قطاع مربع"},"✓","✗"],[{en:"circular section",ar:"قطاع دائري"},"✓","✓"],[{en:"precast",ar:"سابق الصب"},"✓","✗"],[{en:"cast in place",ar:"بيتصب في مكانه"},"✓","✓"],[{en:"diameter above 60 cm",ar:"القطر أكبر من 60 سم"},"✗","✓"],[{en:"existing buildings next door",ar:"مباني قايمة جنب الموقع"},"✗","✓"],[{en:"a hard layer: very stiff or stiff clay, very dense sand, rock",ar:"طبقة صلبة: طين متماسك جداً أو متماسك، رمل كثيف جداً، صخر"},"✗","✓"]],caption:{en:"Every condition that applies to the site must allow the method.",ar:"كل شرط منطبق على الموقع لازم يسمح بالطريقة."}},{t:"p",text:{en:"**Breaking the pile heads (تكسير هامات الخوازيق).** The top of a cast-in-place pile is always its worst concrete — mixed with slurry, soil or laitance. So the pile is cast higher than its **cut-off level**, and before the cap is poured that extra length is broken off, the bars are cleaned and bent into the cap, and the sound concrete enters the cap by a few centimetres.",ar:"**تكسير هامات الخوازيق.** الجزء العلوي من الخازوق اللي بيتصب في مكانه دايماً أوحش خرسانة فيه — مخلوطة بالبنتونيت أو التربة أو اللباني. عشان كده الخازوق بيتصب أعلى من **منسوب القطع**، وقبل صب الهامة الطول الزيادة ده بيتكسر، والأسياخ بتتنضف وتتثني جوه الهامة، والخرسانة السليمة بتدخل الهامة كام سنتيمتر."}},{t:"p",text:{en:"**Load transfer.** A pile hands its load to the ground in two ways: **skin friction** $Q_F$ along the shaft and **end bearing** $Q_b$ under the tip. In a **friction pile** the normal force falls along the shaft (linearly in a uniform soil) to almost nothing at the tip; in an **end-bearing pile**, which crosses weak soil to rest on rock or very dense sand, it stays nearly constant down to the tip. At failure an end-bearing pile punches into the layer under its tip along slip surfaces — Terzaghi's picture of a small, deep footing; a friction pile fails locally in a zone of about 3d around its tip.",ar:"**انتقال الحمل.** الخازوق بيسلّم حمله للتربة بطريقتين: **الاحتكاك الجانبي** $Q_F$ على الجذع و**الارتكاز** $Q_b$ تحت الكعب. في **خازوق الاحتكاك** القوة العمودية بتقل على طول الجذع (خطياً في التربة المتجانسة) لحد ما تقرب من الصفر عند الطرف؛ وفي **خازوق الارتكاز**، اللي بيعدّي التربة الضعيفة ويرتكز على صخر أو رمل كثيف جداً، بتفضل تقريباً ثابتة لحد الطرف. وعند الانهيار خازوق الارتكاز بيخرق الطبقة اللي تحت كعبه على أسطح انزلاق — صورة ترزاجي لقاعدة صغيرة عميقة؛ أما خازوق الاحتكاك فبينهار موضعياً في منطقة حوالي 3d حوالين طرفه."}},{t:"eq",tex:["P = Q_F + Q_b,\\qquad N(z) = P - Q_F(z)"],caption:{en:"Q_F(z): the friction collected between the pile head and the depth z.",ar:"Q_F(z): الاحتكاك المتجمّع من رأس الخازوق لحد العمق z."}},{t:"quiz",q:{kind:"mcq",q:{en:"A site next to an old building needs piles of 0.80 m diameter. Which method?",ar:"موقع جنب مبنى قديم ومحتاج خوازيق قطرها 0.80 م. أنهي طريقة؟"},options:[{en:"Bored",ar:"حفر"},{en:"Driven cast in place",ar:"دق بيتصب في مكانه"},{en:"Precast, driven",ar:"سابق الصب، دق"}],answer:0,explain:{en:"Two conditions rule out driving: Ø > 60 cm and the neighbours. Only a bored (or C.F.A.) pile is left.",ar:"شرطين بيرفضوا الدق: Ø > 60 سم والجيران. مفيش غير خازوق الحفر (أو C.F.A.)."}}}]},{id:"capacity",title:{en:"Capacity: the concrete, and the soil (statical formula)",ar:"القدرة: الخرسانة، والتربة (المعادلة الاستاتيكية)"},blocks:[{t:"p",text:{en:"A pile has two limits and the smaller one wins. **The concrete** (structural formula): a working stress $F_{co}$ = 4.0–5.0 N/mm² on the whole section. **The soil** (statical formula, for bored or driven piles up to Ø60 cm): bearing under the tip plus friction along the shaft, divided by a factor of safety.",ar:"الخازوق ليه حدين والأصغر هو اللي بيكسب. **الخرسانة** (المعادلة الإنشائية): إجهاد تشغيل $F_{co}$ = 4.0–5.0 N/mm² على القطاع كله. **التربة** (المعادلة الاستاتيكية، لخوازيق الحفر أو الدق لحد Ø60 سم): ارتكاز تحت الطرف زائد احتكاك على الجذع، مقسومين على معامل أمان."}},{t:"eq",tex:["Q_{all} = A\\,F_{co},\\qquad T_{all} = n\\,A_{\\phi}\\,F_s"],caption:{en:"Compression on the concrete area A; tension on the bars only, F_s = 160 N/mm² (fy = 360) or 140 N/mm² (fy = 240).",ar:"الضغط على مساحة الخرسانة A؛ والشد على الأسياخ بس، F_s = 160 N/mm² (fy = 360) أو 140 N/mm² (fy = 240)."}},{t:"p",text:{en:"**Example.** A column of 1800 kN on four piles with $F_{co} = 4.5$ N/mm²: each pile takes $1.15\\times1800/4 = 517.5$ kN (15 % for the cap and the soil on it), so $d = \\sqrt{4\\times517.5/(\\pi\\times4500)} = 0.383$ m → **Ø400**. A precast pile 350 × 350 with $F_{co} = 5.0$ carries $0.35^2\\times5000 = 612.5$ kN.",ar:"**مثال.** عمود 1800 kN على أربع خوازيق و $F_{co} = 4.5$ N/mm²: كل خازوق بياخد $1.15\\times1800/4 = 517.5$ kN (15 % للهامة والتربة اللي فوقها)، يبقى $d = \\sqrt{4\\times517.5/(\\pi\\times4500)} = 0.383$ م ← **Ø400**. وخازوق سابق الصب 350 × 350 و $F_{co} = 5.0$ بيشيل $0.35^2\\times5000 = 612.5$ kN."}},{t:"eq",tex:["Q_{ult} = q_b\\,A_b + \\Sigma F_s\\,A_s,\\qquad Q_{all} = \\dfrac{Q_{ult}}{F.O.S.}"],caption:{en:"A_b = πd²/4 or d²; A_s = πd·h or 4d·h for each layer of thickness h. F.O.S. = 3.0 (dead + live), 2.5 (with wind), 2.0 (with earthquake).",ar:"A_b = πd²/4 أو d²؛ و A_s = πd·h أو 4d·h لكل طبقة تخانتها h. معامل الأمان = 3.0 (ميت + حي)، 2.5 (مع الرياح)، 2.0 (مع الزلازل)."}},{t:"table",head:[{en:"Soil",ar:"التربة"},{en:"Under the tip",ar:"تحت الطرف"},{en:"Along the shaft",ar:"على الجذع"}],rows:[[{en:"clay (C)",ar:"طين (C)"},"$q_b = 9\\,C$",{en:"$F_s = C_a = \\alpha C \\le 100$; α = 0.35 for bored piles, the adhesion table for driven ones",ar:"$F_s = C_a = \\alpha C \\le 100$؛ و α = 0.35 لخوازيق الحفر، وجدول الالتصاق لخوازيق الدق"}],[{en:"sand (φ)",ar:"رمل (φ)"},"$q_b = q\\,N_q$","$F_s = K_{HC}\\,\\sigma'\\tan\\delta,\\quad \\delta = 0.75\\,\\varphi$"],[{en:"C–φ soil",ar:"تربة C–φ"},"$q_b = 9\\,C + q\\,N_q$","$F_s = K_{HC}\\,\\sigma'\\tan\\delta + C_a$"]],caption:{en:"q = effective overburden at the tip; σ′ = effective stress at the middle of each layer (γ − 10 below the water table).",ar:"q = الإجهاد الفعّال عند الطرف؛ و σ′ = الإجهاد الفعّال في نص كل طبقة (γ − 10 تحت منسوب المياه)."}},{t:"p",text:{en:"**The tip angle is corrected** for what installation does to the sand: driving compacts it, $\\varphi' = (\\varphi + 40)/2$; boring loosens it, $\\varphi' = \\varphi - 3^\\circ$. Then $N_q$ comes from the table (straight lines in between); the adhesion on a driven pile in clay and the earth-pressure coefficients too:",ar:"**زاوية الطرف بتتصحح** حسب اللي التنفيذ بيعمله في الرمل: الدق بيدمكه، $\\varphi' = (\\varphi + 40)/2$؛ والحفر بيخلخله، $\\varphi' = \\varphi - 3^\\circ$. وبعدين $N_q$ من الجدول (خطوط مستقيمة بين القيم)؛ وكمان الالتصاق على خازوق الدق في الطين ومعاملات ضغط التربة:"}},{t:"table",head:["φ′","25°","30°","35°","40°"],rows:[["$N_q$","15","30","75","150"]]},{t:"table",head:[{en:"C (kN/m²)",ar:"C (kN/m²)"},"0–12.5","12.5–25","25–50","50–100","100–200"],rows:[[{en:"C_a, timber or concrete pile",ar:"C_a، خازوق خشب أو خرسانة"},"0–12.5","12.5–24","24–37.5","37.5–47.5","47.5–65"],[{en:"C_a, steel pile",ar:"C_a، خازوق حديد"},"0–12.5","12.5–23","23–35","35–36","—"]],caption:{en:"Adhesion of clay on displacement (driven) piles.",ar:"التصاق الطين بخوازيق الإزاحة (الدق)."}},{t:"table",head:[{en:"Pile",ar:"الخازوق"},"$K_{HC}$","$K_{HT}$"],rows:[[{en:"H-section",ar:"قطاع H"},"0.5–1.0","0.3–0.5"],[{en:"displacement",ar:"إزاحة"},"1.0–1.5","0.6–1.0"],[{en:"tapered displacement",ar:"إزاحة مسلوب"},"1.5–2.0","1.0–1.3"],[{en:"jetted displacement",ar:"إزاحة بالنفث"},"0.4–0.9","0.3–0.6"],[{en:"bored (Ø < 0.6 m)",ar:"حفر (Ø < 0.6 م)"},"0.7–1.5","0.4–1.0"]],caption:{en:"K_HC in compression, K_HT in tension.",ar:"K_HC في الضغط، و K_HT في الشد."}},{t:"quiz",q:{kind:"num",q:{en:"The tip of a bored pile rests in sand with φ = 35°. Which N_q do you use?",ar:"طرف خازوق حفر قاعد في رمل φ = 35°. هتستخدم N_q كام؟"},answer:48,tol:.001,explain:{en:"$\\varphi' = 35 - 3 = 32^\\circ$, between 30° (30) and 35° (75): $N_q = 30 + 45\\times2/5 = 48$.",ar:"$\\varphi' = 35 - 3 = 32^\\circ$، بين 30° (30) و 35° (75): $N_q = 30 + 45\\times2/5 = 48$."}}}]},{id:"layers",title:{en:"Layered soil, the water table and the 3d rule",ar:"تربة طبقات، ومنسوب المياه، وقاعدة 3d"},blocks:[{t:"p",text:{en:`Real profiles are layered, and the formula follows five rules:
- **end bearing comes only from the layer at the tip**;
- **friction is added layer by layer**, each with σ′ at its own middle;
- a **fill of unknown properties carries nothing**;
- a **sand layer cut by the water table is split** into the part above (bulk γ) and below (γ − 10); a clay layer is not split — its adhesion does not depend on σ′;
- the tip must go **at least 3d into the bearing layer**, otherwise that layer's friction is ignored (its end bearing still counts).`,ar:`القطاعات الحقيقية طبقات، والمعادلة ماشية بخمس قواعد:
- **الارتكاز من الطبقة اللي فيها الطرف بس**؛
- **الاحتكاك بيتجمع طبقة طبقة**، كل طبقة بـ σ′ في نصها؛
- **الردم اللي خواصه مش معروفة مابيشيلش حاجة**؛
- **طبقة الرمل اللي منسوب المياه بيقطعها بتتقسم** لجزء فوق (γ الكلية) وجزء تحت (γ − 10)؛ وطبقة الطين مابتتقسمش — التصاقها مش معتمد على σ′؛
- الطرف لازم يدخل **3d على الأقل في طبقة الارتكاز**، وإلا احتكاك الطبقة دي بيتهمل (وارتكازها بيفضل محسوب).`}},{t:"p",text:{en:"**Example.** The cap underside is 1.0 m below the ground. Fill 1.5 m (γ = 17), clay 4.0 m ($C = 40$ kN/m², γ = 18), silty sand 2.5 m (φ = 30°, γ = 18), then dense sand (φ = 36°, γ = 20); the water table is 3.5 m down. A bored pile Ø500 with its tip at 10.0 m — 2.0 m = 4d into the dense sand ✓. $K_{HC} = 1.0$, α = 0.35, $F_{co} = 4.5$.",ar:"**مثال.** بطن الهامة على عمق 1.0 م. ردم 1.5 م (γ = 17)، وطين 4.0 م ($C = 40$ kN/m²، γ = 18)، ورمل طمي 2.5 م (φ = 30°، γ = 18)، وبعده رمل كثيف (φ = 36°، γ = 20)؛ ومنسوب المياه على 3.5 م. خازوق حفر Ø500 طرفه على 10.0 م — داخل 2.0 م = 4d في الرمل الكثيف ✓. و $K_{HC} = 1.0$، و α = 0.35، و $F_{co} = 4.5$."}},{t:"eq",tex:["q = 17\\times1.5 + 18\\times2.0 + 8\\times2.0 + 8\\times2.5 + 10\\times2.0 = 117.5","\\varphi' = 36 - 3 = 33^\\circ \\Rightarrow N_q = 57,\\qquad Q_b = 117.5\\times57\\times\\dfrac{\\pi\\times0.5^2}{4} = 1315.1"],caption:{en:"Effective stress at the tip (kN/m²), then the end bearing (kN).",ar:"الإجهاد الفعّال عند الطرف (kN/m²)، وبعدين الارتكاز (kN)."}},{t:"table",head:[{en:"Part of the shaft (m)",ar:"جزء الجذع (م)"},"σ′","$F_s$","$A_s$","$Q_s$"],rows:[[{en:"fill 1.0–1.5",ar:"ردم 1.0–1.5"},"—",{en:"ignored",ar:"مهمل"},"0.79","0"],[{en:"clay 1.5–5.5",ar:"طين 1.5–5.5"},"—","$0.35\\times40 = 14.0$","6.28","88.0"],[{en:"silty sand 5.5–8.0",ar:"رمل طمي 5.5–8.0"},"87.5","$87.5\\tan22.5^\\circ = 36.2$","3.93","142.3"],[{en:"dense sand 8.0–10.0",ar:"رمل كثيف 8.0–10.0"},"107.5","$107.5\\tan27^\\circ = 54.8$","3.14","172.1"]],caption:{en:"σ′ and F_s in kN/m², A_s in m², Q_s in kN; δ = ¾φ.",ar:"σ′ و F_s بالـ kN/m²، و A_s بالـ م²، و Q_s بالـ kN؛ و δ = ¾φ."}},{t:"eq",tex:["Q_{ult} = 1315.1 + 402.4 = 1717.4,\\qquad Q_{all} = \\dfrac{1717.4}{3} = 572.5 < A\\,F_{co} = 883.6"],caption:{en:"The soil governs: about 572 kN per pile.",ar:"التربة هي اللي بتحكم: حوالي 572 kN للخازوق."}},{t:"p",text:{en:"**If the tip stopped at 8.5 m** — only 0.5 m = 1d into the dense sand — the 3d rule drops that layer's friction and q falls to 102.5 kN/m²: $Q_b = 1147.2$ and $Q_s = 88.0 + 142.3 = 230.3$ kN, so $Q_{all} = 459.2$ kN — 20 % less for 1.5 m less pile. **A driven square pile 400 × 400** in the same ground: $\\varphi' = (36 + 40)/2 = 38^\\circ$, $N_q = 120$, $Q_b = 117.5\\times120\\times0.16 = 2256$ kN; the clay adhesion now comes from the table ($C_a = 32.1$ kN/m²); $Q_{ult} = 2781.7$ kN and $2781.7/3 = 927.2$ kN — but the concrete allows only $0.16\\times4500 = 720$ kN: **the structural formula governs**.",ar:"**لو الطرف وقف على 8.5 م** — داخل 0.5 م = 1d بس في الرمل الكثيف — قاعدة 3d بتشيل احتكاك الطبقة دي و q بتنزل لـ 102.5 kN/m²: $Q_b = 1147.2$ و $Q_s = 88.0 + 142.3 = 230.3$ kN، يبقى $Q_{all} = 459.2$ kN — أقل بـ 20 % عشان 1.5 م أقل في الخازوق. و**خازوق دق مربع 400 × 400** في نفس التربة: $\\varphi' = (36 + 40)/2 = 38^\\circ$، و $N_q = 120$، و $Q_b = 117.5\\times120\\times0.16 = 2256$ kN؛ والتصاق الطين بقى من الجدول ($C_a = 32.1$ kN/m²)؛ و $Q_{ult} = 2781.7$ kN و $2781.7/3 = 927.2$ kN — بس الخرسانة بتسمح بـ $0.16\\times4500 = 720$ kN بس: **المعادلة الإنشائية هي اللي بتحكم**."}},{t:"quiz",q:{kind:"num",q:{en:"A pile tip at 9.0 m; the soil weighs 18 kN/m³ above the water table (3.0 m down) and 20 kN/m³ below it. Effective overburden q at the tip (kN/m²)?",ar:"طرف خازوق على 9.0 م؛ التربة وزنها 18 kN/m³ فوق منسوب المياه (على 3.0 م) و 20 kN/m³ تحته. الإجهاد الفعّال q عند الطرف (kN/m²)؟"},answer:114,tol:.002,unit:"kN/m²",explain:{en:"$18\\times3 + (20 - 10)\\times6 = 54 + 60 = 114$ kN/m².",ar:"$18\\times3 + (20 - 10)\\times6 = 54 + 60 = 114$ kN/m²."}}}]},{id:"tension-nsf",title:{en:"Tension piles and negative skin friction",ar:"خوازيق الشد والاحتكاك السالب"},blocks:[{t:"p",text:{en:"**A tension pile** has no end bearing: only its shaft and its own weight hold it down. The friction uses $K_{HT}$ instead of $K_{HC}$ (for our bored pile take 0.75), and the weight is added **without** a factor of safety. The bars must carry the pull as well: $T_{all} = n\\,A_\\phi\\,F_s$.",ar:"**خازوق الشد** مالوش ارتكاز: جذعه ووزنه بس اللي ماسكينه. الاحتكاك بيتحسب بـ $K_{HT}$ بدل $K_{HC}$ (لخازوق الحفر بتاعنا خد 0.75)، والوزن بيتضاف **من غير** معامل أمان. والأسياخ لازم تشيل الشد كمان: $T_{all} = n\\,A_\\phi\\,F_s$."}},{t:"eq",tex:["T_{ult} = Q_{s,T} + W_p,\\qquad T_{all} = \\dfrac{Q_{s,T}}{F.O.S.} + W_p"]},{t:"p",text:{en:"**Our pile of the last section in tension:** the clay still gives 88.0 kN and the two sands $0.75\\times(142.3 + 172.1) = 235.8$ kN, so $Q_{s,T} = 323.8$ kN; the pile weighs $0.196\\times9.0\\times25 = 44.2$ kN; $T_{all} = 323.8/3 + 44.2 = 152.1$ kN. Six Ø16 bars (fy = 360) carry $6\\times201.1\\times160 = 193.0$ kN ✓.",ar:"**الخازوق بتاع الجزء اللي فات في الشد:** الطين لسه بيدّي 88.0 kN والرملين $0.75\\times(142.3 + 172.1) = 235.8$ kN، يبقى $Q_{s,T} = 323.8$ kN؛ ووزن الخازوق $0.196\\times9.0\\times25 = 44.2$ kN؛ و $T_{all} = 323.8/3 + 44.2 = 152.1$ kN. وست أسياخ Ø16 (fy = 360) بتشيل $6\\times201.1\\times160 = 193.0$ kN ✓."}},{t:"p",text:{en:"**Negative skin friction (الاحتكاك السالب).** When a soft layer is still settling — under new fill, or because the water table was lowered — it slides down along the pile and **drags it down**. In that layer friction is no longer a resistance but an extra **load**, so it is subtracted from the allowable load **without** the factor of safety (a load does not become safer by being divided). A sand or fill layer riding on the settling clay drags too, with $F_{s3} = 0.3\\,K_{HC}\\,\\sigma'$. A tension pile simply leaves the dragging layer out.",ar:"**الاحتكاك السالب.** لما طبقة طرية تبقى لسه بتهبط — تحت ردم جديد، أو عشان منسوب المياه اتوطّى — بتنزلق لتحت على الخازوق و**بتسحبه معاها**. في الطبقة دي الاحتكاك بطّل يبقى مقاومة وبقى **حمل** زيادة، فبيتطرح من الحمل المسموح **من غير** معامل الأمان (الحمل مابيبقاش آمن أكتر لما نقسمه). وطبقة الرمل أو الردم اللي راكبة على الطين الهابط بتسحب هي كمان، بـ $F_{s3} = 0.3\\,K_{HC}\\,\\sigma'$. أما خازوق الشد فببساطة بيشيل الطبقة اللي بتسحب من الحساب."}},{t:"eq",tex:["Q_{all} = \\dfrac{Q_b + Q_{s1}}{F.O.S.} - Q_{s2} - Q_{s3}"],caption:{en:"Q_s1: friction in the layers that do not settle; Q_s2: drag of the settling clay; Q_s3: drag of the sand or fill above it.",ar:"Q_s1: الاحتكاك في الطبقات اللي مابتهبطش؛ و Q_s2: سحب الطين الهابط؛ و Q_s3: سحب الرمل أو الردم اللي فوقه."}},{t:"p",text:{en:"**Example.** A site raised with 2.0 m of sand fill (φ = 30°, γ = 18) over 6.0 m of soft clay ($C = 15$ kN/m², γ = 17) that is still consolidating, then dense sand (φ = 36°, γ = 20); water at 2.0 m. Bored Ø500, head at 1.0 m, tip at 11.0 m: $q = 18\\times2 + 7\\times6 + 10\\times3 = 108$ kN/m², $Q_b = 108\\times57\\times0.196 = 1208.7$ kN; the dense sand (8–11 m, σ′ = 93) gives $F_s = 93\\tan27^\\circ = 47.4$ and $Q_{s1} = 223.3$ kN; the clay drags $0.35\\times15\\times\\pi\\times0.5\\times6 = 49.5$ kN and the fill between 1 and 2 m $0.3\\times27\\times\\pi\\times0.5\\times1 = 12.7$ kN.",ar:"**مثال.** موقع اتعلّى بردم رملي 2.0 م (φ = 30°، γ = 18) فوق 6.0 م طين طري ($C = 15$ kN/m²، γ = 17) لسه بيتدمج، وبعده رمل كثيف (φ = 36°، γ = 20)؛ والمية على 2.0 م. خازوق حفر Ø500، رأسه على 1.0 م وطرفه على 11.0 م: $q = 18\\times2 + 7\\times6 + 10\\times3 = 108$ kN/m²، و $Q_b = 108\\times57\\times0.196 = 1208.7$ kN؛ والرمل الكثيف (8–11 م، σ′ = 93) بيدّي $F_s = 93\\tan27^\\circ = 47.4$ و $Q_{s1} = 223.3$ kN؛ والطين بيسحب $0.35\\times15\\times\\pi\\times0.5\\times6 = 49.5$ kN والردم بين 1 و 2 م $0.3\\times27\\times\\pi\\times0.5\\times1 = 12.7$ kN."}},{t:"eq",tex:["Q_{all} = \\dfrac{1208.7 + 223.3}{3} - 49.5 - 12.7 = 415.1"],caption:{en:"kN. If nothing settled, the same pile would carry 499.7 kN: the drag costs 17 %.",ar:"kN. لو مفيش حاجة بتهبط، نفس الخازوق كان هيشيل 499.7 kN: السحب بياكل 17 %."}},{t:"note",tone:"tip",text:{en:"**Remedies:** pre-load the soft clay (with sand drains to speed it up) before the piles go in; use bored instead of driven piles; coat the shaft through the settling layer with **bitumen**; enlarge the base; or sleeve the pile in a **double casing** through the settling layer.",ar:"**الحلول:** تحميل مسبق للطين الطري (بمصارف رملية تسرّعه) قبل تنفيذ الخوازيق؛ خوازيق حفر بدل الدق؛ دهان الجذع في الطبقة الهابطة بـ**البيتومين**؛ توسيع القاعدة؛ أو تغليف الخازوق بـ**قيسون مزدوج** في الطبقة الهابطة."}},{t:"lab",lab:"piles",height:500,props:{preset:"negative",missions:a},caption:{en:'The site of the example. Violet arrows: the settling layers drag the pile down; the soil sinks when "negative skin friction" is on. The profile builder below lets you add layers, move the water table and the tip, and switch to a driven or square pile.',ar:'موقع المثال. الأسهم البنفسجي: الطبقات الهابطة بتسحب الخازوق لتحت؛ والتربة بتنزل لما "الاحتكاك السالب" يشتغل. ومنشئ القطاع تحت بيخليك تضيف طبقات، وتحرك منسوب المياه والطرف، وتغيّر لخازوق دق أو مربع.'}},{t:"quiz",q:{kind:"num",q:{en:"Q_b + Q_s1 = 1500 kN, F.O.S. = 3, and the settling layers drag 80 kN. Q_all (kN)?",ar:"Q_b + Q_s1 = 1500 kN، ومعامل الأمان 3، والطبقات الهابطة بتسحب 80 kN. Q_all (kN)؟"},answer:420,tol:.001,unit:"kN",explain:{en:"$1500/3 - 80 = 500 - 80 = 420$ kN — the drag is not divided by 3.",ar:"$1500/3 - 80 = 500 - 80 = 420$ kN — السحب مابيتقسمش على 3."}}}]},{id:"dynamic",title:{en:"Driving records and load tests",ar:"سجلات الدق واختبارات التحميل"},blocks:[{t:"p",text:{en:"**The dynamic (Hiley) formula** reads the capacity of a **driven** pile from its last blows. The useful energy of one blow, $W\\,h\\,\\eta$, pushes the pile down by its permanent **set** S against the resistance of the ground, and squeezes the helmet, the pile and the soil temporarily by C — half of that is given back, so only $C/2$ counts:",ar:"**المعادلة الديناميكية (هايلي)** بتقرا قدرة خازوق **الدق** من آخر ضرباته. الطاقة المفيدة في الضربة، $W\\,h\\,\\eta$، بتنزّل الخازوق بـ**الهبوط الدائم** S ضد مقاومة التربة، وبتضغط الخوذة والخازوق والتربة ضغط مؤقت C — نصه بيرجع، فبيتحسب $C/2$ بس:"}},{t:"eq",tex:["W\\,h\\,\\eta = R_{ult}\\left(S + \\dfrac{C}{2}\\right),\\qquad h = H\\,K,\\qquad C = C_c + C_p + C_q","\\eta = \\dfrac{W + e^2 P}{W + P}\\quad (W \\ge e\\,P)"],caption:{en:"K = 1.0 double-acting or diesel hammer, 0.9 single-acting, 0.8 drop hammer. η follows from W, the driven weight P (pile + helmet) and the rebound e (0.60–0.80 if nothing is known). F.O.S. = 1.5 on rock, 2.0–3.0 in sand and gravel.",ar:"K = 1.0 للمطرقة مزدوجة الفعل أو الديزل، و 0.9 مفردة الفعل، و 0.8 مطرقة السقوط. و η من W والوزن المدقوق P (الخازوق + الخوذة) ومعامل الارتداد e (0.60–0.80 لو مفيش معلومة). معامل الأمان = 1.5 على الصخر، و 2.0–3.0 في الرمل والزلط."}},{t:"p",text:{en:"The hammer is usually about 80 % of the pile weight. The rebound comes from a table — for a precast concrete pile with a plastic or green-heart dolly, 0.4 under a drop, single-acting or diesel hammer and 0.5 under a double-acting one; with a hard-timber dolly 0.25 and 0.4. The formula is an **indication for driven piles in cohesionless soil only**; load tests confirm it.",ar:"المطرقة عادة حوالي 80 % من وزن الخازوق. ومعامل الارتداد من جدول — لخازوق خرسانة سابق الصب بدولي بلاستيك أو خشب صلب، 0.4 تحت مطرقة سقوط أو مفردة الفعل أو ديزل و 0.5 تحت مطرقة مزدوجة الفعل؛ وبدولي خشب 0.25 و 0.4. والمعادلة **قيمة استرشادية لخوازيق الدق في التربة غير المتماسكة بس**؛ واختبارات التحميل هي اللي بتأكدها."}},{t:"p",text:{en:"**Example.** A drop hammer W = 30 kN falling H = 1.5 m (K = 0.8, so h = 1.2 m) drives a precast pile 350 × 350, 10 m long (30.6 kN), with a helmet and dolly of 5 kN: P = 35.6 kN and e = 0.4, so $\\eta = (30 + 0.16\\times35.6)/65.6 = 0.544$. The last blows give S = 8 mm and C = 14 mm: $R_{ult} = 30\\times1.2\\times0.544/(0.008 + 0.007) = 1306$ kN, and with F.O.S. = 2.5, $Q_{all} = 522$ kN.",ar:"**مثال.** مطرقة سقوط W = 30 kN بتقع H = 1.5 م (K = 0.8، يبقى h = 1.2 م) بتدق خازوق سابق الصب 350 × 350 طوله 10 م (30.6 kN) بخوذة ودولي 5 kN: P = 35.6 kN و e = 0.4، يبقى $\\eta = (30 + 0.16\\times35.6)/65.6 = 0.544$. آخر الضربات بتدّي S = 8 مم و C = 14 مم: $R_{ult} = 30\\times1.2\\times0.544/(0.008 + 0.007) = 1306$ kN، وبمعامل أمان 2.5، $Q_{all} = 522$ kN."}},{t:"p",text:{en:"**The pile load test (اختبار تحميل الخازوق)** gives the real answer — about **one test for every 200 piles**. A **working pile** is loaded to 100–150 % of its working load; a **non-working (test) pile** may be taken to failure. A jack pushes the pile against a loaded platform or a beam held down by anchor piles; the settlement is read on **dial gauges** every 2 minutes. The load goes on in steps of the working load and comes off in the same steps, a quarter of an hour each:",ar:"**اختبار تحميل الخازوق** هو اللي بيدّي الإجابة الحقيقية — حوالي **اختبار لكل 200 خازوق**. **الخازوق العامل** بيتحمّل لـ 100–150 % من حمل تشغيله؛ و**الخازوق غير العامل** (خازوق الاختبار) ممكن يوصل للانهيار. جاك بيزق الخازوق قصاد منصة محمّلة أو كمرة ماسكاها خوازيق شد؛ والهبوط بيتقري على **عدادات الهبوط** كل دقيقتين. الحمل بيتحط على خطوات من حمل التشغيل وبيتشال بنفس الخطوات، ربع ساعة لكل خطوة:"}},{t:"table",head:[{en:"Load (of the working load)",ar:"الحمل (من حمل التشغيل)"},"25 %","50 %","75 %","100 %","125 %","150 %"],rows:[[{en:"held for (h)",ar:"مدة الثبات (ساعة)"},"1","1","1","3","3","12"]]},{t:"p",text:{en:"**Reading the curve.** Plot $\\Delta/P$ against $\\Delta$: the later readings fall on a straight line of slope b (**Modified Chin**), and $Q_{ult} = 1/(1.2\\,b)$, with a factor of safety of 2.0 for loads, 1.75 with wind and 1.5 with earthquake. **Brinch Hansen's 90 % criterion** takes as ultimate the load $Q_2$ whose settlement is twice the settlement under $0.9\\,Q_2$.",ar:"**قراية المنحنى.** ارسم $\\Delta/P$ قصاد $\\Delta$: القراءات الأخيرة بتقع على خط مستقيم ميله b (**شين المعدلة**)، و $Q_{ult} = 1/(1.2\\,b)$، بمعامل أمان 2.0 للأحمال و 1.75 مع الرياح و 1.5 مع الزلازل. و**معيار برينش هانسن 90 %** بياخد كحمل أقصى الحمل $Q_2$ اللي هبوطه ضعف الهبوط تحت $0.9\\,Q_2$."}},{t:"eq",tex:["\\dfrac{\\Delta}{P} = a + b\\,\\Delta \\Rightarrow Q_{ult} = \\dfrac{1}{1.2\\,b},\\qquad \\Delta(Q_2) = 2\\,\\Delta(0.9\\,Q_2)"]},{t:"p",text:{en:"**Example.** A test pile for a working load of 500 kN is loaded to 250 %: under 500, 750, 1000, 1125 and 1250 kN it settles 4.0, 8.6, 20.0, 36.0 and 100 mm. Chin with the last points: $\\Delta/P = 20/1000 = 0.0200$ and $36/1125 = 0.0320$, so $b = 0.0120/16 = 0.00075$ and $Q_{ult} = 1/(1.2\\times0.00075) = 1111$ kN → $Q_{all} = 1111/2 = 556$ kN ≥ 500 ✓. Brinch Hansen, reading between the points with straight lines: 1036 kN at 24.6 mm and 1151 kN at 49.1 mm, and $1036/1151 = 0.90$ → $Q_{ult} \\approx 1150$ kN.",ar:"**مثال.** خازوق اختبار حمل تشغيله 500 kN اتحمّل لـ 250 %: تحت 500 و 750 و 1000 و 1125 و 1250 kN هبط 4.0 و 8.6 و 20.0 و 36.0 و 100 مم. شين بآخر النقط: $\\Delta/P = 20/1000 = 0.0200$ و $36/1125 = 0.0320$، يبقى $b = 0.0120/16 = 0.00075$ و $Q_{ult} = 1/(1.2\\times0.00075) = 1111$ kN ← $Q_{all} = 1111/2 = 556$ kN ≥ 500 ✓. وبرينش هانسن، بخطوط مستقيمة بين النقط: 1036 kN عند 24.6 مم و 1151 kN عند 49.1 مم، و $1036/1151 = 0.90$ ← $Q_{ult} \\approx 1150$ kN."}},{t:"lab",lab:"piles",height:500,props:{preset:"loadtest",missions:i},caption:{en:"The test of the example. Edit a settlement in the table, add scatter, move the start of Chin's line — or switch to the Hiley formula and drive a pile.",ar:"اختبار المثال. عدّل هبوط في الجدول، زوّد التشتت، حرّك بداية خط شين — أو روح لمعادلة هايلي ودق خازوق."}},{t:"quiz",q:{kind:"num",q:{en:"A double-acting hammer W = 40 kN, H = 1.0 m, η = 0.70; the set S = 5 mm and C = 10 mm. R_ult (kN)?",ar:"مطرقة مزدوجة الفعل W = 40 kN، و H = 1.0 م، و η = 0.70؛ والهبوط الدائم S = 5 مم و C = 10 مم. R_ult (kN)؟"},answer:2800,tol:.002,unit:"kN",explain:{en:"$h = 1.0\\times1.0$ and $R_{ult} = 40\\times1.0\\times0.70/(0.005 + 0.005) = 2800$ kN.",ar:"$h = 1.0\\times1.0$ و $R_{ult} = 40\\times1.0\\times0.70/(0.005 + 0.005) = 2800$ kN."}}}]},{id:"lateral",title:{en:"Horizontal loads on a pile",ar:"الأحمال الأفقية على الخازوق"},blocks:[{t:"p",text:{en:"A group must also take its horizontal load: $n = \\max(P/Q_{all},\\ H/H_{all})$. The soil resists a sideways push like a bed of springs, $K_h = \\sigma_h/\\delta_h$ (kN/m³). In **over-consolidated clay** it is about constant with depth: $K_h = k_c\\,C_u/d$ with $k_c$ = 35–70 and $C_u = q_{un}/2$. In **sand and normally loaded clay** it grows with depth: $K_h = n\\,z/d$, with n from the table (halved below the water table).",ar:"المجموعة لازم تشيل الحمل الأفقي كمان: $n = \\max(P/Q_{all},\\ H/H_{all})$. التربة بتقاوم الزقة الجانبية زي سرير سوست، $K_h = \\sigma_h/\\delta_h$ (kN/m³). في **الطين زائد التحميل** تقريباً ثابت مع العمق: $K_h = k_c\\,C_u/d$ و $k_c$ = 35–70 و $C_u = q_{un}/2$. وفي **الرمل والطين العادي التحميل** بيزيد مع العمق: $K_h = n\\,z/d$، و n من الجدول (بيتقسم على 2 تحت منسوب المياه)."}},{t:"table",head:[{en:"n (kN/m³)",ar:"n (kN/m³)"},"","","",""],rows:[[{en:"sand, relative density",ar:"رمل، الكثافة النسبية"},"35 %: 4300","65 %: 12 300","85 %: 18 000","100 %: 22 200"],[{en:"normally loaded clay, q_un (kN/m²)",ar:"طين عادي التحميل، q_un (kN/m²)"},"25: 600","50: 1600","100: 3700","—"]]},{t:"p",text:{en:"A **short (rigid)** pile turns as a whole and fails in the soil; a **long (flexible)** pile bends and fails in its own section — the usual case, studied here. Comparing the stiffness of the pile with that of the soil gives a characteristic length:",ar:"الخازوق **القصير (الجاسئ)** بيلف كله وبينهار في التربة؛ والخازوق **الطويل (المرن)** بينحني وبينهار في قطاعه — وده الحالة المعتادة اللي بندرسها. ومقارنة جساءة الخازوق بجساءة التربة بتدّي طول مميز:"}},{t:"eq",tex:["L_o = \\left(\\dfrac{4EI}{K_h\\,d}\\right)^{1/4},\\qquad t = \\left(\\dfrac{EI}{n}\\right)^{1/5},\\qquad E = 2\\times10^7"],caption:{en:"K_h constant → L_o; K_h = n·z/d → t (m). E in kN/m²; I = πd⁴/64 (circle) or d⁴/12 (square).",ar:"K_h ثابت ← L_o؛ و K_h = n·z/d ← t (م). E بالـ kN/m²؛ و I = πd⁴/64 (دايرة) أو d⁴/12 (مربع)."}},{t:"table",head:[{en:"Head",ar:"الرأس"},{en:"K_h constant",ar:"K_h ثابت"},{en:"K_h = n·z/d",ar:"K_h = n·z/d"}],rows:[[{en:"fixed (in a cap)",ar:"مثبت (في هامة)"},"$\\delta = \\dfrac{H}{L_o K_h d},\\ M = \\dfrac{H L_o}{2}$","$\\delta = \\dfrac{0.88\\,H t^3}{EI},\\ M = 0.85\\,H t$"],[{en:"free, with a moment M_o",ar:"حر، بعزم M_o"},"$\\delta = \\dfrac{2H}{L_o K_h d} + \\dfrac{2M_o}{L_o^2 K_h d},\\ M = 0.32\\,H L_o + 0.64\\,M_o$","$\\delta = \\dfrac{2.4\\,H t^3}{EI} + \\dfrac{1.55\\,M_o t^2}{EI},\\ M = 0.77\\,(H t + M_o)$"]],caption:{en:"δ = head deflection, M = largest moment in the pile.",ar:"δ = ترخيم الرأس، و M = أكبر عزم في الخازوق."}},{t:"p",text:{en:"The formulas work both ways. From the allowed head deflection $\\delta_{max}$ find $H_u$; from the moment capacity of the section, $M_u = A_s f_y (d - 50)\\times0.82$, find another $H_u$; take the smaller and divide by the factor of safety (2): $H_{all} = H_u/2$.",ar:"المعادلات بتشتغل في الاتجاهين. من الترخيم المسموح للرأس $\\delta_{max}$ هات $H_u$؛ ومن مقاومة القطاع للعزم، $M_u = A_s f_y (d - 50)\\times0.82$، هات $H_u$ تاني؛ خد الأصغر واقسم على معامل الأمان (2): $H_{all} = H_u/2$."}},{t:"p",text:{en:"**Example.** A bored pile Ø600 in stiff over-consolidated clay, $C_u = 60$ kN/m², $k_c = 50$: $K_h = 50\\times60/0.6 = 5000$ kN/m³; $EI = 2\\times10^7\\times\\pi\\times0.6^4/64 = 127\\,235$ kN·m²; $L_o = (4\\times127\\,235/(5000\\times0.6))^{1/4} = 3.61$ m. Fixed in its cap with $\\delta_{max}$ = 10 mm: $H_u = 0.010\\times3.61\\times5000\\times0.6 = 108.3$ kN and $M = 108.3\\times3.61/2 = 195.4$ kN·m. With 8Ø18 (2036 mm², fy = 400): $M_u = 2036\\times400\\times550\\times0.82 = 367.3$ kN·m ≥ 195.4, so the deflection governs and $H_{all} = 108.3/2 = 54.1$ kN per pile. With a free head the same pile takes only 27.1 kN — fixing the head into the cap doubles it.",ar:"**مثال.** خازوق حفر Ø600 في طين متماسك زائد التحميل، $C_u = 60$ kN/m²، و $k_c = 50$: $K_h = 50\\times60/0.6 = 5000$ kN/m³؛ و $EI = 2\\times10^7\\times\\pi\\times0.6^4/64 = 127\\,235$ kN·m²؛ و $L_o = (4\\times127\\,235/(5000\\times0.6))^{1/4} = 3.61$ م. مثبت في هامته و $\\delta_{max}$ = 10 مم: $H_u = 0.010\\times3.61\\times5000\\times0.6 = 108.3$ kN و $M = 108.3\\times3.61/2 = 195.4$ kN·m. وبـ 8Ø18 (2036 مم²، fy = 400): $M_u = 2036\\times400\\times550\\times0.82 = 367.3$ kN·m ≥ 195.4، يبقى الترخيم هو اللي بيحكم و $H_{all} = 108.3/2 = 54.1$ kN للخازوق. وبرأس حر نفس الخازوق بياخد 27.1 kN بس — تثبيت الرأس في الهامة بيضاعفه."}},{t:"note",tone:"tip",text:{en:"Every lab of this episode has a **Lateral** mode (the switch at the top of Inputs): it draws the deflected pile, its moment diagram and the soil reaction for these formulas, and tells whether the deflection or the section governs.",ar:"كل معمل في الحلقة دي فيه وضع **أفقي** (المفتاح اللي فوق في المدخلات): بيرسم الخازوق وهو مترخّم ومنحنى العزوم ورد فعل التربة للمعادلات دي، وبيقولك الترخيم ولا القطاع اللي بيحكم."}},{t:"quiz",q:{kind:"num",q:{en:"A pile with EI = 100 000 kN·m² stands in sand with n = 5000 kN/m³. Relative stiffness t (m)?",ar:"خازوق EI = 100 000 kN·m² في رمل n = 5000 kN/m³. الجساءة النسبية t (م)؟"},answer:1.821,tol:.003,unit:"m",explain:{en:"$t = (100\\,000/5000)^{1/5} = 20^{0.2} = 1.82$ m.",ar:"$t = (100\\,000/5000)^{1/5} = 20^{0.2} = 1.82$ م."}}}]},{id:"cap-layout",title:{en:"Pile caps: spacing and standard layouts",ar:"هامات الخوازيق: التباعد والترتيبات القياسية"},blocks:[{t:"p",text:{en:"The cap spreads the column load over its piles. The simple rule — **every pile takes P/n** — holds only if the cap is **rigid** (effective depth at least twice the pile diameter, $d \\ge 2\\phi$) and the group is symmetric about the load: **C.G. of the piles = C.G. of the cap = C.G. of the loads**. The number of piles adds 15 % for the cap and the soil above it:",ar:"الهامة بتوزّع حمل العمود على خوازيقها. القاعدة البسيطة — **كل خازوق بياخد P/n** — بتنفع بس لو الهامة **جاسئة** (العمق الفعّال على الأقل ضعف قطر الخازوق، $d \\ge 2\\phi$) والمجموعة متماثلة حوالين الحمل: **مركز الخوازيق = مركز الهامة = مركز الأحمال**. وعدد الخوازيق بيزود 15 % للهامة والتربة اللي فوقها:"}},{t:"eq",tex:["n = \\dfrac{1.15\\,P}{Q_{all}}"],caption:{en:"Rounded up; P = working column load.",ar:"بيتقرّب لفوق؛ و P = حمل العمود في التشغيل."}},{t:"table",head:[{en:"Piles",ar:"الخوازيق"},{en:"Least spacing",ar:"أقل تباعد"},{en:"Largest spacing",ar:"أكبر تباعد"},{en:"Edge distance",ar:"مسافة الحافة"}],rows:[[{en:"friction",ar:"احتكاك"},"3d","6d","d–1.5d"],[{en:"end bearing",ar:"ارتكاز"},"2.5d","6d","d–1.5d"],[{en:"on rock",ar:"على صخر"},"2d","6d","d–1.5d"]],caption:{en:"If the pile type is not known use 3d. The edge distance is measured from the pile axis to the edge of the cap.",ar:"لو نوع الخازوق مش معروف خد 3d. ومسافة الحافة من محور الخازوق لحرف الهامة."}},{t:"p",text:{en:"**Standard layouts** keep the centroid under the column: 1 pile right under it; 2 in a line; 3 in a triangle with the column at its centroid; 4 in a square; 5 = a square with one in the middle; 6 = two rows of three (or a hexagon); 7 = a hexagon with one in the middle; 8 = staggered rows 3 + 2 + 3 — better than a 3 × 3 square with its centre missing; 9 = 3 × 3. A cap on one or two piles cannot resist a moment across their line: tie it with **ground beams** (السملات).",ar:"**الترتيبات القياسية** بتخلّي المركز تحت العمود: خازوق واحد تحته على طول؛ اتنين في خط؛ تلاتة في مثلث والعمود في مركزه؛ أربعة في مربع؛ خمسة = مربع وواحد في النص؛ ستة = صفين كل صف تلاتة (أو شكل سداسي)؛ سبعة = سداسي وواحد في النص؛ تمانية = صفوف متخالفة 3 + 2 + 3 — أحسن من مربع 3 × 3 ناقص النص؛ تسعة = 3 × 3. والهامة اللي على خازوق أو اتنين مابتقدرش تقاوم عزم عمودي على خطهم: اربطها بـ**السملات**."}},{t:"quiz",q:{kind:"mcq",q:{en:"Bored friction piles Ø500 in one cap: the spacing S must lie between…",ar:"خوازيق حفر احتكاك Ø500 في هامة واحدة: التباعد S لازم يبقى بين…"},options:[{en:"1.50 and 3.00 m",ar:"1.50 و 3.00 م"},{en:"1.25 and 3.00 m",ar:"1.25 و 3.00 م"},{en:"1.00 and 2.50 m",ar:"1.00 و 2.50 م"}],answer:0,explain:{en:"$S_{min} = 3d = 1.5$ m for friction piles, $S_{max} = 6d = 3.0$ m (2.5d = 1.25 m is for end-bearing piles).",ar:"$S_{min} = 3d = 1.5$ م لخوازيق الاحتكاك، و $S_{max} = 6d = 3.0$ م (2.5d = 1.25 م لخوازيق الارتكاز)."}}}]},{id:"cap-axial",title:{en:"Designing a cap under an axial load",ar:"تصميم هامة تحت حمل محوري"},blocks:[{t:"steps",items:[{en:"$n = 1.15P/Q_{all}$ → a standard layout with $S \\approx 3d$ and an edge distance of d–1.5d → the size of the cap.",ar:"$n = 1.15P/Q_{all}$ ← ترتيب قياسي بـ $S \\approx 3d$ ومسافة حافة d–1.5d ← مقاس الهامة."},{en:"Every pile: $Q_u = 1.5P/n$.",ar:"كل خازوق: $Q_u = 1.5P/n$."},{en:"Moments at the column faces: $M = \\Sigma Q_u\\,z$ over the piles beyond each face (z = pile axis to the face).",ar:"العزوم عند وشوش العمود: $M = \\Sigma Q_u\\,z$ للخوازيق اللي بعد كل وش (z = من محور الخازوق للوش)."},{en:"$d = C_1\\sqrt{M/(f_{cu}B)}$ with $C_1 = 5$, but never less than $2\\phi$; $t = d$ + a cover of 100–150 mm.",ar:"$d = C_1\\sqrt{M/(f_{cu}B)}$ و $C_1 = 5$، بس عمره ما يقل عن $2\\phi$؛ و $t = d$ + غطاء 100–150 مم."},{en:"One-way shear on a line at d from each face: the piles beyond the line count — a pile cut by the line by the part of its diameter beyond it; if every pile is inside the line there is no check; $q \\le 0.16\\sqrt{f_{cu}/\\gamma_c}$.",ar:"القص في اتجاه واحد على خط على بعد d من كل وش: الخوازيق اللي بعد الخط بتتحسب — والخازوق اللي الخط بيقطعه بالجزء من قطره اللي بعد الخط؛ ولو كل الخوازيق جوه الخط مفيش مراجعة؛ و $q \\le 0.16\\sqrt{f_{cu}/\\gamma_c}$."},{en:"Punching at d/2 around the column: $Q_p = 1.5P - \\Sigma Q_u$ (piles inside), $q_p = Q_p/(b_o d) \\le 0.316(0.5 + a/b)\\sqrt{f_{cu}/\\gamma_c}$ with $0.5 + a/b$ taken at most 1 (a = the shorter column side).",ar:"القص الثاقب على بعد d/2 حوالين العمود: $Q_p = 1.5P - \\Sigma Q_u$ (الخوازيق اللي جوه)، و $q_p = Q_p/(b_o d) \\le 0.316(0.5 + a/b)\\sqrt{f_{cu}/\\gamma_c}$ و $0.5 + a/b$ أقصاها 1 (a = ضلع العمود الأقصر)."},{en:"$A_s = M/(J f_y d)$ with J = 0.826, spread over the cap width, at least 1.5d mm² per metre. A plain-concrete layer of 10–15 cm under the cap; the piles are reinforced like columns with a spiral of pitch ≤ 15 cm, their bars anchored into the cap. On the drawings the piles under the cap are dashed circles, each with its own small axes.",ar:"$A_s = M/(J f_y d)$ و J = 0.826، متوزع على عرض الهامة، وعلى الأقل 1.5d مم² في المتر. طبقة خرسانة عادية 10–15 سم تحت الهامة؛ والخوازيق بتتسلح زي الأعمدة بكانة حلزونية خطوتها ≤ 15 سم، وأسياخها متثبتة في الهامة. وفي اللوحات الخوازيق اللي تحت الهامة بتترسم دواير متقطعة، ولكل خازوق محاوره الصغيرة."}]},{t:"p",text:{en:"**Example.** Column 800 × 500 mm, P = 3600 kN; piles Ø500 with $Q_{all} = 700$ kN; $f_{cu} = 30$, $f_y = 400$. $n = 1.15\\times3600/700 = 5.91$ → **6 piles**: two rows of three at S = 1.5 m, edge distance 0.5 m → cap 4.0 × 2.5 m with the long side of the column along the cap. Every pile: $Q_u = 1.5\\times3600/6 = 900$ kN.",ar:"**مثال.** عمود 800 × 500 مم، و P = 3600 kN؛ وخوازيق Ø500 و $Q_{all} = 700$ kN؛ و $f_{cu} = 30$، و $f_y = 400$. $n = 1.15\\times3600/700 = 5.91$ ← **6 خوازيق**: صفين كل صف تلاتة بتباعد 1.5 م ومسافة حافة 0.5 م ← هامة 4.0 × 2.5 م وضلع العمود الطويل ماشي مع طول الهامة. كل خازوق: $Q_u = 1.5\\times3600/6 = 900$ kN."}},{t:"eq",tex:["M_1 = 2\\times900\\times(1.5 - 0.4) = 1980,\\qquad M_2 = 3\\times900\\times(0.75 - 0.25) = 1350","d = \\max\\left(5\\sqrt{\\dfrac{1980\\times10^6}{30\\times2500}},\\ 2\\times500\\right) = \\max(812,\\ 1000) = 1000,\\qquad t = 1100"],caption:{en:"M_1 in kN·m acts over the 2.5 m width, M_2 over the 4.0 m length; depths in mm.",ar:"M_1 بالـ kN·m على العرض 2.5 م، و M_2 على الطول 4.0 م؛ والأعماق بالمم."}},{t:"p",text:{en:"**Shear:** the line 1.0 m beyond the 800 mm face is 1.4 m from the column axis and cuts the outer piles (1.25–1.75 m): 70 % of each lies beyond it, so $Q = 2\\times900\\times0.7 = 1260$ kN and $q = 1260\\times10^3/(2500\\times1000) = 0.504 \\le 0.716$ N/mm² ✓; the other way every pile is inside the line — no check. **Punching** on the 1.8 × 1.5 m perimeter: the two middle piles are half inside, $Q_p = 5400 - 900 = 4500$ kN and $q_p = 4500\\times10^3/(6600\\times1000) = 0.682 \\le 1.413$ N/mm² ✓ ($0.5 + 500/800 = 1.125$ → 1.0). **Steel:** $1980\\times10^6/(0.826\\times400\\times1000) = 5993$ mm² → 2397 mm²/m → **7Ø22/m**; the other way 4086 mm² → 1021 mm²/m < 1.5d = 1500 → **8Ø16/m**.",ar:"**القص:** الخط اللي على بعد 1.0 م من الوش 800 مم بيبقى على 1.4 م من محور العمود وبيقطع الخوازيق الطرفية (1.25–1.75 م): 70 % من كل واحد بعد الخط، يبقى $Q = 2\\times900\\times0.7 = 1260$ kN و $q = 1260\\times10^3/(2500\\times1000) = 0.504 \\le 0.716$ N/mm² ✓؛ وفي الاتجاه التاني كل الخوازيق جوه الخط — مفيش مراجعة. **القص الثاقب** على محيط 1.8 × 1.5 م: الخازوقين اللي في النص نصهم جوه، $Q_p = 5400 - 900 = 4500$ kN و $q_p = 4500\\times10^3/(6600\\times1000) = 0.682 \\le 1.413$ N/mm² ✓ ($0.5 + 500/800 = 1.125$ ← 1.0). **الحديد:** $1980\\times10^6/(0.826\\times400\\times1000) = 5993$ مم² ← 2397 مم²/م ← **7Ø22/م**؛ وفي الاتجاه التاني 4086 مم² ← 1021 مم²/م < 1.5d = 1500 ← **8Ø16/م**."}},{t:"quiz",q:{kind:"num",q:{en:"Punching: 1.5P = 4800 kN, the piles inside the perimeter carry 1200 kN, b_o = 6.0 m, d = 0.9 m. q_p (N/mm²)?",ar:"القص الثاقب: 1.5P = 4800 kN، والخوازيق اللي جوه المحيط شايلة 1200 kN، و b_o = 6.0 م، و d = 0.9 م. q_p (N/mm²)؟"},answer:.6667,tol:.003,unit:"N/mm²",explain:{en:"$(4800 - 1200)\\times10^3/(6000\\times900) = 0.667$ N/mm².",ar:"$(4800 - 1200)\\times10^3/(6000\\times900) = 0.667$ N/mm²."}}}]},{id:"cap-moment",title:{en:"Caps under a moment, and the defective pile",ar:"هامات تحت عزم، والخازوق المعيوب"},blocks:[{t:"p",text:{en:"With a moment the pile loads vary across the group like the stress in a section under N and M — with $\\Sigma x^2$ in place of the moment of inertia. The number of piles grows with the eccentricities (in metres, used as plain numbers):",ar:"مع العزم أحمال الخوازيق بتتغير على المجموعة زي الإجهاد في قطاع تحت N و M — و $\\Sigma x^2$ مكان عزم القصور. وعدد الخوازيق بيزيد مع اللامركزية (بالمتر، كأرقام):"}},{t:"eq",tex:["n = \\dfrac{1.15\\,P}{Q_{all}}(1 + e_x)(1 + e_y),\\qquad e_x = \\dfrac{M_y}{P},\\quad e_y = \\dfrac{M_x}{P}","Q_i = \\dfrac{1.15\\,P}{n} \\pm \\dfrac{M_y\\,x_i}{\\Sigma x^2} \\pm \\dfrac{M_x\\,y_i}{\\Sigma y^2} \\le Q_{all},\\qquad Q_{min} \\ge 0","Q_{ui} = \\dfrac{1.5\\,P}{n} \\pm \\dfrac{1.5\\,M_y\\,x_i}{\\Sigma x^2} \\pm \\dfrac{1.5\\,M_x\\,y_i}{\\Sigma y^2}"],caption:{en:"The working check (middle line) and the ultimate reactions for the design of the cap (last line). x and y from the group centroid, positive on the compressed side. A negative Q is a tension pile — check it against T_all, or add piles.",ar:"مراجعة التشغيل (السطر الأوسط) وردود الأفعال القصوى لتصميم الهامة (السطر الأخير). x و y من مركز المجموعة، موجبين ناحية الضغط. و Q السالبة معناها خازوق شد — راجعه على T_all، أو زوّد خوازيق."}},{t:"p",text:{en:"**Example.** Column 900 × 600, P = 4200 kN with a permanent $M_y = 700$ kN·m; piles Ø500 with $Q_{all} = 750$ kN: $e_x = 0.167$ → $n = 6.44\\times1.167 = 7.51$ → **8 piles** (3 + 2 + 3 at S = 1.5 m) with $\\Sigma x^2 = 4\\times1.5^2 + 2\\times0.75^2 = 10.125$ m². Working: $Q = 603.75 \\pm 700\\times1.5/10.125 = 603.75 \\pm 103.7$ → **707.5 ≤ 750 ✓** and **500.0 > 0 ✓**. Ultimate: $787.5 \\pm 155.6$ → 943.1 kN on the compressed edge, and the moment at the 900 mm face on that side: $2\\times943.1\\times1.05 + 865.3\\times0.30 = 2240$ kN·m.",ar:"**مثال.** عمود 900 × 600، و P = 4200 kN وعزم دائم $M_y = 700$ kN·m؛ وخوازيق Ø500 و $Q_{all} = 750$ kN: $e_x = 0.167$ ← $n = 6.44\\times1.167 = 7.51$ ← **8 خوازيق** (3 + 2 + 3 بتباعد 1.5 م) و $\\Sigma x^2 = 4\\times1.5^2 + 2\\times0.75^2 = 10.125$ م². التشغيل: $Q = 603.75 \\pm 700\\times1.5/10.125 = 603.75 \\pm 103.7$ ← **707.5 ≤ 750 ✓** و **500.0 > 0 ✓**. الأقصى: $787.5 \\pm 155.6$ ← 943.1 kN على ناحية الضغط، والعزم عند الوش 900 مم في الناحية دي: $2\\times943.1\\times1.05 + 865.3\\times0.30 = 2240$ kN·m."}},{t:"p",text:{en:"**A defective pile.** Integrity tests sometimes find a broken or short pile after the group is built. It is left out: the centroid of the remaining piles moves, the column load becomes eccentric to the group, and the extra moments are $M_y = P\\,e_x$ and $M_x = P\\,e_y$.",ar:"**الخازوق المعيوب.** اختبارات السلامة ساعات بتلاقي خازوق مكسور أو قصير بعد ما المجموعة تتنفذ. بيتشال من الحساب: مركز الخوازيق الباقية بيتحرك، وحمل العمود بيبقى لامركزي على المجموعة، والعزوم الزيادة $M_y = P\\,e_x$ و $M_x = P\\,e_y$."}},{t:"eq",tex:["e_x = \\dfrac{\\Sigma A_i\\,x_i}{\\Sigma A_i},\\qquad e_y = \\dfrac{\\Sigma A_i\\,y_i}{\\Sigma A_i},\\qquad M_y = P\\,e_x,\\qquad M_x = P\\,e_y"]},{t:"p",text:{en:"**Example.** Four piles Ø400 at S = 1.2 m under P = 1200 kN, $Q_{all} = 400$ kN: normally $1.15\\times1200/4 = 345$ kN each ✓. One corner pile turns out defective: the centroid of the other three moves 0.2 m in x and in y, so $M_x = M_y = 1200\\times0.2 = 240$ kN·m with $\\Sigma x^2 = \\Sigma y^2 = 0.96$ m². The two neighbours of the missing pile now carry $460 + 240\\times0.8/0.96 - 240\\times0.4/0.96 = 560$ kN > 400 ✗ and the far corner only 260 kN: the group must be repaired with extra piles.",ar:"**مثال.** أربع خوازيق Ø400 بتباعد 1.2 م تحت P = 1200 kN و $Q_{all} = 400$ kN: في العادي $1.15\\times1200/4 = 345$ kN للواحد ✓. خازوق ركن طلع معيوب: مركز التلاتة الباقيين بيتحرك 0.2 م في x وفي y، يبقى $M_x = M_y = 1200\\times0.2 = 240$ kN·m و $\\Sigma x^2 = \\Sigma y^2 = 0.96$ م². جيران الخازوق اللي اتشال بقوا شايلين $460 + 240\\times0.8/0.96 - 240\\times0.4/0.96 = 560$ kN > 400 ✗ والركن البعيد 260 kN بس: المجموعة لازم تتصلّح بخوازيق زيادة."}},{t:"lab",lab:"piles",height:500,props:{preset:"moment",missions:n},caption:{en:"The 8-pile example. Slide M_y and M_x: piles go from blue (light) through green to amber (full), red above Q_all, violet when pulled. Click a pile (3-D or plan) to make it defective; the orange planes are the shear lines at d, the violet box the punching perimeter.",ar:"مثال الـ 8 خوازيق. حرّك M_y و M_x: الخوازيق بتروح من الأزرق (خفيف) للأخضر للكهرماني (مليان)، وأحمر فوق Q_all، وبنفسجي لما يتشد. اضغط على خازوق (3D أو المسقط) عشان تخليه معيوب؛ والمستويات البرتقاني خطوط القص عند d، والصندوق البنفسجي محيط القص الثاقب."}},{t:"quiz",q:{kind:"num",q:{en:"Four piles at S = 1.2 m; one corner pile is defective. How far (m) does the centroid of the remaining three move in each direction?",ar:"أربع خوازيق بتباعد 1.2 م؛ خازوق ركن معيوب. مركز التلاتة الباقيين بيتحرك قد إيه (م) في كل اتجاه؟"},answer:.2,tol:.002,unit:"m",explain:{en:"The piles at (±0.6, ±0.6) without one corner: $\\bar{x} = (-0.6 + 0.6 - 0.6)/3 = -0.2$ m, and the same in y.",ar:"الخوازيق عند (±0.6، ±0.6) من غير ركن: $\\bar{x} = (-0.6 + 0.6 - 0.6)/3 = -0.2$ م، ونفس الكلام في y."}}}]},{id:"property",title:{en:"At the property line: strap beams on piles and combined caps",ar:"عند حد الجار: كمرة رباط على خوازيق وهامات مشتركة"},blocks:[{t:"p",text:{en:"A column on the property line cannot sit over the centre of its own pile group: the rig needs room, and the first pile axis must stay about **0.75–1.25 m** from the line. When the column axis is closer than about **1.25–1.50 m** to the line, or its piles would cross it, two solutions remain: a **strap beam on piles** tying the edge column to an interior one, or one **combined pile cap** under both columns.",ar:"العمود اللي على حد الجار مايقدرش يقعد فوق مركز مجموعة خوازيقه: الماكينة محتاجة مكان، وأول محور خوازيق لازم يبعد حوالي **0.75–1.25 م** عن الحد. ولما محور العمود يبقى أقرب من حوالي **1.25–1.50 م** للحد، أو خوازيقه هتعدّي الحد، بيفضل حلّين: **كمرة رباط على خوازيق** بتربط عمود الجار بعمود داخلي، أو **هامة مشتركة** واحدة تحت العمودين."}},{t:"p",text:{en:"**Strap beam on piles (كمرة رباط على خوازيق).** The pile group of cap 1 is centred at a distance e from the edge column, e ≈ 0.1–0.2 S, and the beam balances the eccentricity:",ar:"**كمرة رباط على خوازيق.** مجموعة خوازيق الهامة 1 مركزها على بعد e من عمود الجار، و e ≈ 0.1–0.2 S، والكمرة بتوازن اللامركزية:"}},{t:"eq",tex:["R_1 = \\dfrac{P_1\\,S}{S - e},\\qquad R_2 = P_1 + P_2 - R_1,\\qquad N_i = \\dfrac{1.15\\,R_i}{Q_{all}},\\qquad Q_{iu} = \\dfrac{1.5\\,R_i}{N_i}"],caption:{en:"S = column spacing. Cap 1 is centred on R1, cap 2 under C2; the pile reactions act on the beam as point loads.",ar:"S = المسافة بين العمودين. الهامة 1 مركزها على R1، والهامة 2 تحت C2؛ وردود أفعال الخوازيق بتأثر على الكمرة كأحمال مركزة."}},{t:"p",text:{en:"Checks: the nearest pile axes of the two groups at least $S_{min}$ apart (otherwise a combined cap is needed); the strap beam designed for its moments with $C_1 = 4.5$, a width b not less than the columns (40–80 cm), and stirrups by the older shear limits $q_{cu} = 0.24\\sqrt{f_{cu}/\\gamma_c}$, $q_{su} = q_u - q_{cu}/2$; each cap designed as a cantilever from the faces of the beam (moment at the face, shear at d from it).",ar:"المراجعات: أقرب محاور خوازيق في المجموعتين تبعد عن بعض $S_{min}$ على الأقل (وإلا محتاجين هامة مشتركة)؛ وكمرة الرباط بتتصمم لعزومها بـ $C_1 = 4.5$، وعرض b مش أقل من الأعمدة (40–80 سم)، وكانات بحدود القص القديمة $q_{cu} = 0.24\\sqrt{f_{cu}/\\gamma_c}$ و $q_{su} = q_u - q_{cu}/2$؛ وكل هامة بتتصمم ككابولي من وشوش الكمرة (العزم عند الوش، والقص على بعد d منه)."}},{t:"p",text:{en:"**Example.** C1 400 × 600 at the line, P1 = 1500 kN; C2 400 × 800 at S = 6.0 m, P2 = 2400 kN; piles Ø400 (S = 1.2 m) with $Q_{all} = 650$ kN; e = 1.0 m: $R_1 = 1500\\times6/5 = 1800$ kN, $R_2 = 2100$ kN; $N_1 = 1.15\\times1800/650 = 3.18$ → 4 and $N_2 = 3.72$ → 4. The resultant of cap 1 lies $0.2 + 1.0 = 1.2$ m from the line and the first row at 0.8 m. Rows of **2 + 2** would need the second row only $X = 0.8$ m behind the first — less than 1.2 m ✗. Rows of **3 + 1**: $(3\\times0.8 + 1\\times(0.8 + X))/4 = 1.2$ → $X = 1.6$ m ✓ (diagonal 2.0 m ✓). The two groups stay 3.2 m apart ✓. With $Q_{1u} = 675$ and $Q_{2u} = 787.5$ kN the largest moment in the beam is 1710 kN·m, over the rear pile of cap 1; with b = 700 mm and $f_{cu} = 30$: $d = 4.5\\sqrt{1710\\times10^6/(30\\times700)} = 1284$ → 1300 mm.",ar:"**مثال.** C1 400 × 600 على الحد، و P1 = 1500 kN؛ و C2 400 × 800 على بعد S = 6.0 م، و P2 = 2400 kN؛ وخوازيق Ø400 (S = 1.2 م) و $Q_{all} = 650$ kN؛ و e = 1.0 م: $R_1 = 1500\\times6/5 = 1800$ kN، و $R_2 = 2100$ kN؛ و $N_1 = 1.15\\times1800/650 = 3.18$ ← 4 و $N_2 = 3.72$ ← 4. محصلة الهامة 1 على بعد $0.2 + 1.0 = 1.2$ م من الحد وأول صف على 0.8 م. صفوف **2 + 2** محتاجة الصف التاني على بعد $X = 0.8$ م بس من الأول — أقل من 1.2 م ✗. صفوف **3 + 1**: $(3\\times0.8 + 1\\times(0.8 + X))/4 = 1.2$ ← $X = 1.6$ م ✓ (القطر 2.0 م ✓). والمجموعتين بعاد عن بعض 3.2 م ✓. وبـ $Q_{1u} = 675$ و $Q_{2u} = 787.5$ kN أكبر عزم في الكمرة 1710 kN·m، فوق الخازوق الورّاني في الهامة 1؛ وبـ b = 700 مم و $f_{cu} = 30$: $d = 4.5\\sqrt{1710\\times10^6/(30\\times700)} = 1284$ ← 1300 مم."}},{t:"p",text:{en:"**Combined pile cap (هامة مشتركة).** One cap under both columns: $n = 1.15R/Q_{all}$ with R = P1 + P2, and the piles arranged in rows so that their centroid falls on R. Two rows are fixed by the rules; the position of the third follows from the centroid equation, and then $S_{min} \\le X \\le S_{max}$ must hold — diagonals included. The design is **not** $Q_u = 1.5R/N$ for every pile: a long cap bends and the piles under the columns take more. It is modelled with shell elements on springs $K_s = Q_{all}/\\Delta$.",ar:"**هامة مشتركة.** هامة واحدة تحت العمودين: $n = 1.15R/Q_{all}$ و R = P1 + P2، والخوازيق بتترص في صفوف بحيث مركزها يقع على R. صفين بيتحددوا بالقواعد؛ ومكان التالت بيطلع من معادلة المركز، وبعدين لازم $S_{min} \\le X \\le S_{max}$ — والأقطار كمان. والتصميم **مش** $Q_u = 1.5R/N$ لكل خازوق: الهامة الطويلة بتنحني والخوازيق اللي تحت الأعمدة بتاخد أكتر. بتتعمل موديل عناصر قشرية على سوست $K_s = Q_{all}/\\Delta$."}},{t:"eq",tex:["\\bar{X} = \\dfrac{\\Sigma n_i\\,X_i}{\\Sigma n_i},\\qquad K_s = \\dfrac{Q_{all}}{\\Delta_{pile}}"]},{t:"p",text:{en:"**Example.** P1 = 1500 kN (column 500 × 500 at the line), P2 = 2700 kN at S = 4.0 m, piles Ø500 (3d = 1.5 m, 6d = 3.0 m) with $Q_{all} = 650$ kN: $n = 1.15\\times4200/650 = 7.43$ → 8. R lies $0.25 + 2700\\times4/4200 = 2.82$ m from the line, i.e. 2.07 m from the first row (0.75 m from the line). Rows 3 + 3 + 2: $[3\\times0 + 3\\times1.5 + 2(1.5 + X)]/8 = 2.07$ → X = 4.54 m ✗ (> 6d); 3 + 3 + 3: X = 3.21 m ✗; **2 + 3 + 3**: X = 2.52 m ✓. For a pile that settles 10 mm under $Q_{all}$, $K_s = 650/0.010 = 65\\,000$ kN/m.",ar:"**مثال.** P1 = 1500 kN (عمود 500 × 500 على الحد)، و P2 = 2700 kN على بعد S = 4.0 م، وخوازيق Ø500 (3d = 1.5 م، و 6d = 3.0 م) و $Q_{all} = 650$ kN: $n = 1.15\\times4200/650 = 7.43$ ← 8. R على بعد $0.25 + 2700\\times4/4200 = 2.82$ م من الحد، يعني 2.07 م من أول صف (على 0.75 م من الحد). صفوف 3 + 3 + 2: $[3\\times0 + 3\\times1.5 + 2(1.5 + X)]/8 = 2.07$ ← X = 4.54 م ✗ (> 6d)؛ و 3 + 3 + 3: X = 3.21 م ✗؛ و **2 + 3 + 3**: X = 2.52 م ✓. ولخازوق بيهبط 10 مم تحت $Q_{all}$، $K_s = 650/0.010 = 65\\,000$ kN/m."}},{t:"lab",lab:"piles",height:500,props:{preset:"strap",missions:s},caption:{en:"The strap example with cap 1 still on 2 + 2 rows — fix it. Then bring the columns closer and switch to the combined cap.",ar:"مثال كمرة الرباط والهامة 1 لسه على صفوف 2 + 2 — صلّحها. وبعدين قرّب العمودين وروح للهامة المشتركة."}},{t:"quiz",q:{kind:"num",q:{en:"Strap beam on piles: P1 = 1200 kN, S = 5.0 m, e = 0.8 m. R1 (kN)?",ar:"كمرة رباط على خوازيق: P1 = 1200 kN، و S = 5.0 م، و e = 0.8 م. R1 (kN)؟"},answer:1428.57,tol:.002,unit:"kN",explain:{en:"$R_1 = 1200\\times5.0/(5.0 - 0.8) = 6000/4.2 = 1428.6$ kN.",ar:"$R_1 = 1200\\times5.0/(5.0 - 0.8) = 6000/4.2 = 1428.6$ kN."}}}]},{id:"apply",title:{en:"Your building: what if the ground were weak?",ar:"مبناك: لو الأرض ضعيفة؟"},blocks:[{t:"p",text:{en:"Your building stands on isolated footings: the soil allows 150 kN/m², and a footing under every column spreads its load. **Suppose instead** that the site had **8 m of soft clay** ($C_u = 20$ kN/m², γ = 17 kN/m³) **over dense sand** (φ = 36°, γ = 19 kN/m³), with the water table 2 m down. Footings would sink into the clay. The answer: **bored piles Ø400** — no vibration next to the neighbours — with their heads under the caps at 1.5 m and their tips at 9.5 m, **1.5 m = 3.75d into the sand** (≥ 3d ✓); each pile is 8.0 m long (≥ 10d ✓).",ar:"مبناك قاعد على قواعد منفصلة: التربة بتسمح بـ 150 kN/m²، وتحت كل عمود قاعدة بتفرش حمله. **افترض بدل كده** إن الموقع فيه **8 م طين طري** ($C_u = 20$ kN/m²، γ = 17 kN/m³) **فوق رمل كثيف** (φ = 36°، γ = 19 kN/m³)، ومنسوب المياه على 2 م. القواعد كانت هتغطس في الطين. الحل: **خوازيق حفر Ø400** — من غير اهتزاز جنب الجيران — رؤوسها تحت الهامات على 1.5 م وأطرافها على 9.5 م، **داخلة 1.5 م = 3.75d في الرمل** (≥ 3d ✓)؛ وطول الخازوق 8.0 م (≥ 10d ✓)."}},{t:"eq",tex:["q = 17\\times2 + 7\\times6 + 9\\times1.5 = 89.5,\\qquad \\varphi' = 33^\\circ,\\ N_q = 57 \\Rightarrow Q_b = 89.5\\times57\\times0.1257 = 641.1","Q_{s1} = 0.35\\times20\\times\\pi\\times0.4\\times6.5 = 57.2,\\qquad Q_{s2} = 82.75\\tan27^\\circ\\times\\pi\\times0.4\\times1.5 = 79.5","Q_{all} = \\dfrac{641.1 + 57.2 + 79.5}{3} = 259.2 < A\\,F_{co} = 0.1257\\times4500 = 565.5"],caption:{en:"kN/m² and kN. Q_s1: the clay from 1.5 to 8.0 m; Q_s2: the sand from 8.0 to 9.5 m. The soil governs: about 259 kN per pile.",ar:"kN/m² و kN. و Q_s1: الطين من 1.5 لـ 8.0 م؛ و Q_s2: الرمل من 8.0 لـ 9.5 م. التربة هي اللي بتحكم: حوالي 259 kN للخازوق."}},{t:"table",head:[{en:"Column",ar:"العمود"},{en:"P (kN)",ar:"P (kN)"},"$1.15P/Q_{all}$",{en:"Piles",ar:"الخوازيق"}],rows:[["B2","492.1","2.18","3"],["B3","431.5","1.91","2"],["A2","378.8","1.68","2"],["B1","293.2","1.30","2"],["A3","289.5","1.28","2"],["B4","262.2","1.16","2"],["C2","258.5","1.15","2"],["C3","219.0","0.97","1"],["A1","178.9","0.79","1"],["A4","129.5","0.57","1"],["C1","123.9","0.55","1"],["C4","104.5","0.46","1"]],caption:{en:"20 piles in all, service column loads of your building.",ar:"20 خازوق في المجموع، بأحمال التشغيل لأعمدة مبناك."}},{t:"p",text:{en:"**B2, the heaviest column (492.1 kN): three piles in a triangle** of side 1.2 m (3d) with the column at its centroid and an edge distance of 0.5 m → cap 2.2 × 2.05 m. Working: $1.15\\times492.1/3 = 188.6$ kN ≤ 259.2 ✓; ultimate $Q_u = 1.5\\times492.1/3 = 246.05$ kN. The moment at the 300 mm faces: $246.05\\times(0.6 - 0.15) = 110.7$ kN·m — flexure needs only 232 mm, but the cap must be rigid: $d = 2\\phi = 800$ mm, **t = 900 mm**. The shear lines 0.8 m from the faces pass outside every pile: no one-way shear. Punching on the 1.1 × 1.3 m perimeter: the three piles are partly inside (281.2 kN of their reactions), so $Q_p = 738.2 - 281.2 = 456.9$ kN and $q_p = 0.119 \\le 1.29$ N/mm² ✓. Steel: 419 mm² over 2.05 m is far below $1.5d = 1200$ mm²/m → **6Ø16/m** both ways.",ar:"**B2، أتقل عمود (492.1 kN): تلات خوازيق في مثلث** ضلعه 1.2 م (3d) والعمود في مركزه ومسافة حافة 0.5 م ← هامة 2.2 × 2.05 م. التشغيل: $1.15\\times492.1/3 = 188.6$ kN ≤ 259.2 ✓؛ والأقصى $Q_u = 1.5\\times492.1/3 = 246.05$ kN. العزم عند الوشوش 300 مم: $246.05\\times(0.6 - 0.15) = 110.7$ kN·m — الانحناء محتاج 232 مم بس، لكن الهامة لازم تبقى جاسئة: $d = 2\\phi = 800$ مم، **t = 900 مم**. وخطوط القص على بعد 0.8 م من الوشوش بتعدّي برّه كل الخوازيق: مفيش قص في اتجاه واحد. والقص الثاقب على محيط 1.1 × 1.3 م: التلات خوازيق جزء منهم جوه (281.2 kN من ردود أفعالهم)، يبقى $Q_p = 738.2 - 281.2 = 456.9$ kN و $q_p = 0.119 \\le 1.29$ N/mm² ✓. الحديد: 419 مم² على 2.05 م أقل بكتير من $1.5d = 1200$ مم²/م ← **6Ø16/م** في الاتجاهين."}},{t:"p",text:{en:"**The edge columns.** A2 (378.8 kN) gets two piles in line with its 500 mm side, cap 1.0 × 2.2 m: $Q_u = 284.1$ kN, $M = 284.1\\times(0.6 - 0.25) = 99.4$ kN·m, again $d = 800$, t = 900 mm and 6Ø16/m; A3, B1, B4 and C2 — and the interior column B3 — are caps of the same type. The corners A1, A4, C1, C4 and the light edge column C3 stand on a single pile under a 1.0 × 1.0 m block. One or two piles cannot hold a moment across their line, so the caps are tied by **ground beams** (السملات) in both directions.",ar:"**أعمدة الأطراف.** A2 (378.8 kN) بياخد خازوقين على استقامة ضلعه 500 مم، وهامة 1.0 × 2.2 م: $Q_u = 284.1$ kN، و $M = 284.1\\times(0.6 - 0.25) = 99.4$ kN·m، وبرضه $d = 800$ و t = 900 مم و 6Ø16/م؛ و A3 و B1 و B4 و C2 — والعمود الداخلي B3 — هامات من نفس النوع. والأركان A1 و A4 و C1 و C4 وعمود الطرف الخفيف C3 قاعدين على خازوق واحد تحت بلوك 1.0 × 1.0 م. وخازوق أو اتنين مايقدروش يمسكوا عزم عمودي على خطهم، فالهامات بتتربط بـ**السملات** في الاتجاهين."}},{t:"note",tone:"tip",text:{en:"**Verdict.** 20 bored piles and 12 caps 900 mm deep instead of 12 footings: on weak ground that is the safe answer. On the real site (150 kN/m²) the isolated footings of the shallow-foundations episode are cheaper and faster — piles are chosen by the ground, not by habit.",ar:"**الخلاصة.** 20 خازوق حفر و 12 هامة عمقها 900 مم بدل 12 قاعدة: على الأرض الضعيفة ده الحل الآمن. وعلى الموقع الحقيقي (150 kN/m²) القواعد المنفصلة بتاعة حلقة الأساسات السطحية أرخص وأسرع — الخوازيق بتتختار حسب التربة، مش بالعادة."}},{t:"widget",w:"building",props:{focus:"F-B2",tags:["footings","cols-g","cols-1","beams-1","slab-1","materials","pile-option"]}},{t:"quiz",q:{kind:"num",q:{en:"Column B3 carries 431.5 kN and one pile is allowed 259.2 kN. n = 1.15P/Q_all?",ar:"العمود B3 شايل 431.5 kN والخازوق الواحد مسموح له بـ 259.2 kN. n = 1.15P/Q_all؟"},answer:1.914,tol:.003,explain:{en:"$1.15\\times431.5/259.2 = 1.91$ → 2 piles, each $1.15\\times431.5/2 = 248$ kN ≤ 259.2 ✓.",ar:"$1.15\\times431.5/259.2 = 1.91$ ← خازوقين، كل واحد $1.15\\times431.5/2 = 248$ kN ≤ 259.2 ✓."}}}]}],quiz:[{kind:"num",q:{en:"A precast pile 350 × 350 mm with F_co = 5.0 N/mm². Structural Q_all (kN)?",ar:"خازوق سابق الصب 350 × 350 مم و F_co = 5.0 N/mm². Q_all الإنشائي (kN)؟"},answer:612.5,tol:.001,unit:"kN",explain:{en:"$0.35^2\\times5.0\\times10^3 = 612.5$ kN.",ar:"$0.35^2\\times5.0\\times10^3 = 612.5$ kN."}},{kind:"num",q:{en:"A driven pile has its tip in sand with φ = 30°. Corrected angle φ′ (°)?",ar:"خازوق دق طرفه في رمل φ = 30°. الزاوية المصححة φ′ (°)؟"},answer:35,tol:.001,unit:"°",explain:{en:"Driving compacts the sand: $\\varphi' = (30 + 40)/2 = 35^\\circ$ (and then $N_q = 75$).",ar:"الدق بيدمك الرمل: $\\varphi' = (30 + 40)/2 = 35^\\circ$ (ويبقى $N_q = 75$)."}},{kind:"mcq",q:{en:"The drag of a settling layer on a pile is…",ar:"سحب الطبقة الهابطة على الخازوق هو…"},options:[{en:"a load: subtracted from Q_all without the factor of safety",ar:"حمل: بيتطرح من Q_all من غير معامل الأمان"},{en:"a resistance: added and divided by the factor of safety",ar:"مقاومة: بتتضاف وتتقسم على معامل الأمان"},{en:"ignored for bored piles",ar:"بيتهمل لخوازيق الحفر"}],answer:0,explain:{en:"$Q_{all} = (Q_b + Q_{s1})/F.O.S. - Q_{s2}$: the drag is not made smaller by the factor of safety.",ar:"$Q_{all} = (Q_b + Q_{s1})/F.O.S. - Q_{s2}$: السحب مابيصغرش بمعامل الأمان."}},{kind:"num",q:{en:"Single-acting hammer W = 50 kN, H = 1.2 m, η = 0.60; set S = 6 mm, C = 12 mm. R_ult (kN)?",ar:"مطرقة مفردة الفعل W = 50 kN، و H = 1.2 م، و η = 0.60؛ والهبوط الدائم S = 6 مم، و C = 12 مم. R_ult (kN)؟"},answer:2700,tol:.002,unit:"kN",explain:{en:"$h = 1.2\\times0.9 = 1.08$ m; $R_{ult} = 50\\times1.08\\times0.60/(0.006 + 0.006) = 2700$ kN.",ar:"$h = 1.2\\times0.9 = 1.08$ م؛ و $R_{ult} = 50\\times1.08\\times0.60/(0.006 + 0.006) = 2700$ kN."}},{kind:"num",q:{en:"On the Δ/P–Δ plot of a load test the straight line has slope b = 0.0005 kN⁻¹. Modified Chin Q_ult (kN)?",ar:"على رسم Δ/P–Δ لاختبار تحميل الخط المستقيم ميله b = 0.0005 kN⁻¹. Q_ult بشين المعدلة (kN)؟"},answer:1666.67,tol:.002,unit:"kN",explain:{en:"$Q_{ult} = 1/(1.2\\times0.0005) = 1667$ kN.",ar:"$Q_{ult} = 1/(1.2\\times0.0005) = 1667$ kN."}},{kind:"tf",q:{en:"With K_h constant and the same allowed deflection, a pile fixed into its cap takes twice the horizontal load of the same pile with a free head.",ar:"مع K_h ثابت ونفس الترخيم المسموح، الخازوق المثبت في هامته بياخد ضعف الحمل الأفقي لنفس الخازوق برأس حر."},answer:!0,explain:{en:"Fixed: $\\delta = H/(L_o K_h d)$; free: $\\delta = 2H/(L_o K_h d)$ — the same δ needs half the load on a free head.",ar:"مثبت: $\\delta = H/(L_o K_h d)$؛ حر: $\\delta = 2H/(L_o K_h d)$ — نفس δ بتيجي من نص الحمل على الرأس الحر."}},{kind:"num",q:{en:"A 3 × 3 pile cap (S = 1.5 m) under P = 4000 kN and M_y = 600 kN·m (working). Largest working pile load (kN)?",ar:"هامة 3 × 3 خوازيق (S = 1.5 م) تحت P = 4000 kN و M_y = 600 kN·m (تشغيل). أكبر حمل تشغيل على خازوق (kN)؟"},answer:577.78,tol:.002,unit:"kN",explain:{en:"$\\Sigma x^2 = 6\\times1.5^2 = 13.5$; $Q = 1.15\\times4000/9 + 600\\times1.5/13.5 = 511.1 + 66.7 = 577.8$ kN.",ar:"$\\Sigma x^2 = 6\\times1.5^2 = 13.5$؛ و $Q = 1.15\\times4000/9 + 600\\times1.5/13.5 = 511.1 + 66.7 = 577.8$ kN."}},{kind:"num",q:{en:"Combined pile cap: rows of 3, 3 and 3 piles; the second row 1.8 m behind the first; the resultant 2.3 m from the first row. Distance X from the second to the third row (m)?",ar:"هامة مشتركة: صفوف 3 و 3 و 3 خوازيق؛ والصف التاني على بعد 1.8 م من الأول؛ والمحصلة على بعد 2.3 م من أول صف. المسافة X من الصف التاني للتالت (م)؟"},answer:3.3,tol:.002,unit:"m",explain:{en:"$[3\\times0 + 3\\times1.8 + 3(1.8 + X)]/9 = 2.3$ → $20.7 = 10.8 + 3X$ → $X = 3.3$ m.",ar:"$[3\\times0 + 3\\times1.8 + 3(1.8 + X)]/9 = 2.3$ ← $20.7 = 10.8 + 3X$ ← $X = 3.3$ م."}}]};export{o as default};
